import subprocess, time, os, sys, shlex
SESSION="walk"
def run(cmd, **kw):
    return subprocess.run(cmd, shell=True, capture_output=True, text=True, **kw)
def start(cwd="/tmp/testdir", args="", env=None, w=80, h=24, prog="/workspace/executable"):
    run(f"tmux kill-session -t {SESSION} 2>/dev/null")
    time.sleep(0.2)
    envstr=""
    if env:
        for k,v in env.items():
            envstr+=f"{k}={shlex.quote(v)} "
    cmd=f"cd {shlex.quote(cwd)} && {envstr}{prog} {args}; echo EXITCODE:$?; sleep 1000"
    subprocess.run(["tmux","new-session","-d","-s",SESSION,"-x",str(w),"-y",str(h),cmd])
    time.sleep(0.8)
def cap(esc=False):
    args=["tmux","capture-pane","-t",SESSION,"-p","-S","-200"]
    if esc: args.append("-e")
    out=subprocess.check_output(args).decode()
    return out
def send(*keys, delay=0.35):
    for k in keys:
        if isinstance(k, str) and k.startswith("L:"):
            subprocess.run(["tmux","send-keys","-t",SESSION,"-l",k[2:]])
        else:
            subprocess.run(["tmux","send-keys","-t",SESSION,k])
        time.sleep(delay)
def kill():
    run(f"tmux kill-session -t {SESSION} 2>/dev/null")
