import sys; sys.path.insert(0,"/tmp")
from harness import *
import os, shutil, re, subprocess
def reset():
    shutil.rmtree("/tmp/brtest", ignore_errors=True)
    os.makedirs("/tmp/brtest/subdir", exist_ok=True)
    open("/tmp/brtest/aaa.txt","w").write("aaa content\nline2\n")
    open("/tmp/brtest/bbb.txt","w").write("bbb\n")
    open("/tmp/brtest/subdir/inner.txt","w").write("inner\n")
def files():
    out=[]
    for root,dirs,fs in os.walk("/tmp/brtest"):
        for x in dirs+fs:
            out.append(os.path.relpath(os.path.join(root,x),"/tmp/brtest"))
    return sorted(out)
def trial_key(key, is_literal=False):
    reset()
    start(cwd="/tmp/brtest", env={"TERM":"xterm-256color"})
    init=cap()
    if is_literal:
        send(f"L:{key}")
    else:
        send(key)
    txt=cap()
    exited="EXITCODE" in txt
    # get selected by opening? we know position maybe first screen lines
    print(f"KEY {key!r} literal={is_literal} exited={exited} files={files()} screen_change={txt!=init}")
    if txt!=init:
        # print first 15 lines plain diff
        for i,(a,b) in enumerate(zip(init.splitlines(), txt.splitlines())):
            if a!=b:
                print("  line",i,repr(b))
        if len(txt.splitlines())>len(init.splitlines()):
            print("  extra",txt.splitlines()[len(init.splitlines()):])
    kill()
import sys
keys=sys.argv[1:]
for k in keys:
    if k.startswith("L:"):
        trial_key(k[2:], True)
    else:
        trial_key(k, False)
