    subprocess.run("rm -rf /tmp/brtest; mkdir -p /tmp/brtest/sub; printf 'aaa\\n' >/tmp/brtest/aaa.txt; printf 'i\\n'>/tmp/brtest/sub/inner.txt", shell=True)
