# compare to etc parsed
patterns={}
names={}
for raw in open("etc/icons"):
    line=raw.strip()
    if not line or line.startswith("#"): continue
    parts=line.split()
    if len(parts)<2: continue
    pat,icon=parts[0],parts[1]
    if pat.startswith("'*"): pat=pat.strip("'")
    if pat.startswith("*."):
        patterns[pat[2:].lower()]=icon
    elif pat.startswith("*"):
        names[pat[1:].lower()]=icon
# load walk observed
import ast
obs={}
for line in open("/tmp/icons_out.txt"):
    line=line.strip()
    if not line: continue
    # repr token + hex
    # line like "'\\ue000 file.ext' 0xe..."
    # use eval of first token?
    try:
        tok=ast.literal_eval(line.split(" 0x")[0])
    except Exception as e:
        print("parse fail",line,e); continue
    icon, name = tok.split(" ",1)
    obs[name]=icon
mismatch=[]
for name,icon in obs.items():
    ext=name.split(".",1)[1] if "." in name else ""
    exp=patterns.get(ext)
    if exp!=icon:
        mismatch.append((name,icon,exp))
print("mismatches", mismatch)
