import sys; sys.path.insert(0,"/tmp")
from harness import *
import os, shutil, re
def make(n, length):
    shutil.rmtree("/tmp/gd", ignore_errors=True); os.makedirs("/tmp/gd")
    for i in range(1,n+1):
        name = f"f{i:03d}" + "x"*max(0,length-8) + ".txt"
        open(f"/tmp/gd/{name}","w").write("x\n")
def grid(w,h):
    start(cwd="/tmp/gd", args="", env={"TERM":"xterm-256color"}, w=w,h=h)
    txt=cap(); kill()
    lines=[l for l in txt.splitlines()[1:] if l.strip()]
    cols=max(len(l.split()) for l in lines) if lines else 0
    per=None
    if lines and len(lines[0].split())>=2:
        m=re.search(r'f(\d+)', lines[0].split()[1]); per=int(m.group(1))-1
    else: per=len(lines)
    return per,cols
for length in [4,8,13,20,30]:
    make(30,length)
    print(f"L={length} 80x24 {grid(80,24)} 80x10 {grid(80,10)} 40x24 {grid(40,24)} 200x100 {grid(200,100)}")
