{"command":"cat > utils.go <<'EOF'
package main

import (
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"os/user"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"unicode"
	"unicode/utf8"
)

// fileInfo returns information about a file following symlinks. It panics on
// an error, mirroring the observed behaviour when a dangling symlink is
// activated.
func fileInfo(dir string, file fs.DirEntry) fs.FileInfo {
	info, err := os.Stat(filepath.Join(dir, file.Name()))
	if err != nil {
		panic(err)
	}
	return info
}

func readAndFilter(path string, hideHidden, dirOnly bool) ([]fs.DirEntry, error) {
	entries, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}
	out := make([]fs.DirEntry, 0, len(entries))
	for _, e := range entries {
		if hideHidden && strings.HasPrefix(e.Name(), ".") {
			continue
		}
		if dirOnly && !e.IsDir() {
			continue
		}
		out = append(out, e)
	}
	return out, nil
}

func displayName(e fs.DirEntry, icons bool) string {
	name := e.Name()
	if e.IsDir() {
		name += "/"
	}
	if icons {
		return iconFor(e) + " " + name
	}
	return name
}

// iconFor implements the observed precedence: directories and special file
// types first, then exact file names, then extensions, executable files and
// finally regular files.
func iconFor(e fs.DirEntry) string {
	info, err := e.Info()
	var mode fs.FileMode
	if err == nil && info != nil {
		mode = info.Mode()
	} else {
		mode = e.Type()
	}
	if e.IsDir() {
		if mode&fs.ModeSticky != 0 {
			return "t"
		}
		return "\uf115"
	}
	// Special modes are checked before names/extensions.
	switch {
	case mode&fs.ModeSetuid != 0:
		return "u"
	case mode&fs.ModeSetgid != 0:
		return "g"
	case mode&fs.ModeNamedPipe != 0:
		return "p"
	case mode&fs.ModeSocket != 0:
		return "s"
	case mode&fs.ModeDevice != 0 && mode&fs.ModeCharDevice != 0:
		return "c"
	case mode&fs.ModeDevice != 0:
		return "b"
	}
	if icon, ok := iconByName[strings.ToLower(e.Name())]; ok {
		return icon
	}
	ext := strings.ToLower(strings.TrimPrefix(filepath.Ext(e.Name()), "."))
	if icon, ok := iconByExt[ext]; ok {
		return icon
	}
	if mode&0o111 != 0 {
		return "\uf427"
	}
	return "\uf40e"
}

func displayPath(path string) string {
	home, err := os.UserHomeDir()
	if err == nil && home != "" {
		return strings.Replace(path, home, "~", 1)
	}
	return path
}

func makeBox(msg string) string {
	line := strings.Repeat("─", len([]rune(msg))+2)
	return "╭" + line + "╮\n│ " + msg + " │\n╰" + line + "╯"
}

// visualWidth computes the printed width of a string, ignoring ANSI escape
// sequences and treating tabs as advancing to a multiple of eight (an
// approximation which is sufficient for the plain strings handled here).
func visualWidth(s string) int {
	w := 0
	inEsc := false
	for _, r := range s {
		if r == '\x1b' {
			inEsc = true
			continue
		}
		if inEsc {
			if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') {
				inEsc = false
			}
			continue
		}
		if r == '\t' {
			w += 8 - (w % 8)
			continue
		}
		w += runeWidth(r)
	}
	return w
}

func runeWidth(r rune) int {
	if r < 0x20 || (r >= 0x7f && r < 0xa0) {
		return 0
	}
	// East asian wide ranges - a small approximation.
	if (r >= 0x1100 && r <= 0x115f) || (r >= 0x2e80 && r <= 0xa4cf) || (r >= 0xac00 && r <= 0xd7a3) || (r >= 0xf900 && r <= 0xfaff) || (r >= 0xfe30 && r <= 0xfe6f) || (r >= 0xff00 && r <= 0xff60) || (r >= 0x20000 && r <= 0x3fffd) {
		return 2
	}
	return 1
}

func padRightVisual(s string, width int) string {
	w := visualWidth(s)
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func truncateLeftVisual(s string, width int) string {
	if width < 0 {
		width = 0
	}
	if visualWidth(s) <= width {
		return s
	}
	// Keep the right-most characters, as the original does.
	r := []rune(s)
	// Account for ANSI sequences crudely by operating on plain strings only.
	// All strings passed here are plain paths.
	for len(r) > 0 && visualWidth(string(r)) > width {
		r = r[1:]
	}
	return string(r)
}

func humanSize(size int64) string {
	const kb = 1024
	const mb = 1024 * kb
	const gb = 1024 * mb
	const tb = 1024 * gb
	const pb = 1024 * tb
	switch {
	case size < kb:
		return fmt.Sprintf("%dB", size)
	case size < mb:
		return fmt.Sprintf("%.1fKB", float64(size)/float64(kb))
	case size < gb:
		return fmt.Sprintf("%.1fMB", float64(size)/float64(mb))
	case size < tb:
		return fmt.Sprintf("%.1fGB", float64(size)/float64(gb))
	case size < pb:
		return fmt.Sprintf("%.1fTB", float64(size)/float64(tb))
	default:
		return fmt.Sprintf("%.1fPB", float64(size)/float64(pb))
	}
}

func modeString(m fs.FileMode) string {
	var b [10]byte
	switch {
	case m.IsDir():
		b[0] = 'd'
	case m&fs.ModeSymlink != 0:
		b[0] = 'l'
	case m&fs.ModeNamedPipe != 0:
		b[0] = 'p'
	case m&fs.ModeSocket != 0:
		b[0] = 's'
	case m&fs.ModeDevice != 0 && m&fs.ModeCharDevice != 0:
		b[0] = 'c'
	case m&fs.ModeDevice != 0:
		b[0] = 'b'
	default:
		b[0] = '-'
	}
	perm := m.Perm()
	chars := []byte("rwxrwxrwx")
	for i := 0; i < 9; i++ {
		if perm&(1<<uint(8-i)) != 0 {
			b[1+i] = chars[i]
		} else {
			b[1+i] = '-'
		}
	}
	// setuid / setgid / sticky adjustments in the execute positions
	if m&fs.ModeSetuid != 0 {
		if b[3] == 'x' {
			b[3] = 's'
		} else {
			b[3] = 'S'
		}
	}
	if m&fs.ModeSetgid != 0 {
		if b[6] == 'x' {
			b[6] = 's'
		} else {
			b[6] = 'S'
		}
	}
	if m&fs.ModeSticky != 0 {
		if b[9] == 'x' {
			b[9] = 't'
		} else {
			b[9] = 'T'
		}
	}
	return string(b[:])
}

func ownerString(info fs.FileInfo) string {
	if info == nil {
		return ""
	}
	st, ok := info.Sys().(*syscall.Stat_t)
	if !ok || st == nil {
		return ""
	}
	uid := strconv.FormatUint(uint64(st.Uid), 10)
	gid := strconv.FormatUint(uint64(st.Gid), 10)
	uname := uid
	if u, err := user.LookupId(uid); err == nil {
		uname = u.Username
	}
	gname := gid
	if g, err := user.LookupGroupId(gid); err == nil {
		gname = g.Name
	}
	return uname + " " + gname
}

func sanitizeContent(b []byte) string {
	// Keep printable ASCII, newlines and tabs only.
	var sb strings.Builder
	for _, r := range string(b) {
		if r == '\n' || r == '\t' {
			sb.WriteRune(r)
		} else if r >= 0x20 && r <= 0x7e {
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

func isImageExt(name string) bool {
	switch strings.ToLower(filepath.Ext(name)) {
	case ".jpg", ".jpeg", ".png", ".gif":
		return true
	}
	return false
}

// executeRemove performs a (possibly custom) removal for a single path.
func executeRemove(removeCmd string, cmdSet bool, path string) {
	if !cmdSet {
		_ = os.RemoveAll(path)
		return
	}
	if removeCmd == "" {
		// An explicitly empty command fails, just like exec of an empty name.
		return
	}
	cmd := exec.Command(removeCmd, path)
	_ = cmd.Run()
}

func writeClipboard(text string) {
	// Replicates the clipboard helper behaviour on Linux: xclip is preferred,
	// falling back to xsel. Errors are ignored by callers.
	if path, err := exec.LookPath("xclip"); err == nil {
		cmd := exec.Command(path, "-in", "-selection", "clipboard")
		cmd.Stdin = strings.NewReader(text)
		_ = cmd.Run()
		return
	}
	if path, err := exec.LookPath("xsel"); err == nil {
		cmd := exec.Command(path, "--input", "--clipboard")
		cmd.Stdin = strings.NewReader(text)
		_ = cmd.Run()
		return
	}
}

func isPrintableRune(r rune) bool {
	return unicode.IsPrint(r) && r <= 0x7e
}

func ensureUTF8(s string) bool { return utf8.ValidString(s) }

var _ = isPrintableRune
var _ = ensureUTF8
