// computeColumns chooses a column count for the layout.  It approximates the
// algorithm of the original: rows are roughly a third of the terminal
// height, columns are limited by the available width, and the special case
// of very many files uses two columns.
func computeColumns(n, maxLen, termWidth, termHeight int) (cols, rows int) {
	if n <= 0 {
		return 0, 0
	}
	if n > 100 {
		cols = 2
		if termWidth > 0 && maxLen > 0 {
			// Even the two column layout may not fit.
			if (maxLen+4)*2-4 > termWidth && termWidth < maxLen {
				cols = 1
			}
		}
		rows = (n + cols - 1) / cols
		return cols, rows
	}
	rowsTarget := 10
	if termHeight > 0 {
		rowsTarget = termHeight / 3
		if rowsTarget < 3 {
			rowsTarget = 3
		}
		// The target is not a hard maximum (single column views show the
		// whole list), but it drives the column calculation.
		if n <= 10 && termHeight >= 20 {
