	if termWidth > 0 && maxLen > 0 {
		maxCols := (termWidth + 4) / (maxLen + 4)
		if maxCols < 1 {
			maxCols = 1
		}
		if cols > maxCols {
			cols = maxCols
		}
	}
	rows = (n + cols - 1) / cols
