	n := len(items)
	cols, rows := computeColumns(n, maxLen, m.width, m.height)
	if cols <= 0 {
		cols = 1
	}
	if rows <= 0 {
		rows = n
	}
	// Column widths (per column)
	colWidth := make([]int, cols)
	for c := 0; c < cols; c++ {
		w := 0
		for r := 0; r < rows; r++ {
			idx := c*rows + r
			if idx >= n {
				break
			}
			if vw := visualWidth(items[idx].text); vw > w {
				w = vw
			}
		}
		colWidth[c] = w
	}
	var lines []string
	for r := 0; r < rows; r++ {
		var sb strings.Builder
		for c := 0; c < cols; c++ {
			idx := c*rows + r
			if idx >= n {
				continue
			}
			if c > 0 {
				sb.WriteString("    ")
			}
			cell := padRightVisual(items[idx].text, colWidth[c])
			if items[idx].index == selected {
				if marked {
					cell = m.styleMarked(cell)
				} else {
					cell = m.styleSelected(cell)
				}
			}
			sb.WriteString(cell)
		}
		lines = append(lines, sb.String())
	}
	return strings.Join(lines, "\n")
}

// computeColumns chooses a column count for the layout.  It approximates the
// algorithm of the original: rows are roughly a third of the terminal
// height, columns are limited by the available width, and the special case
// of very many files uses two columns.
func computeColumns(n, maxLen, termWidth, termHeight int) (cols, rows int) {
	if n <= 0 {
		return 0, 0
	}
	if n > 100 {
		cols = 2
		if termWidth > 0 && maxLen > 0 {
			// Even the two column layout may not fit.
			if (maxLen+4)*2-4 > termWidth && termWidth < maxLen {
				cols = 1
			}
		}
		rows = (n + cols - 1) / cols
		return cols, rows
	}
	rowsTarget := 10
	if termHeight > 0 {
		rowsTarget = termHeight / 3
		if rowsTarget < 3 {
			rowsTarget = 3
		}
		// The target is not a hard maximum (single column views show the
		// whole list), but it drives the column calculation.
		if n <= 10 && termHeight >= 20 {
			rowsTarget = 10
		}
	}
	cols = (n + rowsTarget - 1) / rowsTarget
	if cols < 1 {
		cols = 1
	}
	// Column cap from width using the longest entry.
	if termWidth > 0 && maxLen > 0 {
		maxCols := (termWidth + 4) / (maxLen + 4)
		if maxCols < 1 {
			maxCols = 1
		}
		if cols > maxCols {
			cols = maxCols
		}
	}
	rows = (n + cols - 1) / cols
	return cols, rows
}

func (m *model) previewForSelected() (name string, content string, has bool) {
	f := m.currentEntry()
	if f == nil {
		return "", makeBox("Invalid file to preview"), false
	}
	name = f.Name()
	full := filepath.Join(m.path, name)
	info, err := os.Stat(full)
	if err != nil {
		return name, makeBox(err.Error()), true
	}
	if info.IsDir() {
		entries, err := os.ReadDir(full)
		if err != nil {
			return name, makeBox(err.Error()), true
		}
		if len(entries) == 0 {
			return name, makeBox("No files"), true
		}
		ents := make([]entry, len(entries))
		for i, e := range entries {
			ents[i] = entry{DirEntry: e}
		}
		// Directory previews do not highlight any item.
		return name, m.renderFilesListPreview(ents), true
	}
	if isImageExt(name) {
		return name, makeBox("No image preview available"), true
	}
	data, err := os.ReadFile(full)
	if err != nil {
		return name, err.Error(), true
	}
	if !utf8.Valid(data) {
		return name, makeBox("No preview available"), true
	}
	clean := sanitizeContent(data)
	return name, highlightContent(name, clean), true
}

func (m *model) renderFilesListPreview(files []entry) string {
	// Same layout as the main list but never with a selection.
	saved := m.config.icons
	_ = saved
	// We temporarily render using the same helper with no selection; the
	// helper uses m for icons/styles which are irrelevant without selection.
	return m.renderFilesList(files, -1, false)
}
