			end := strings.Index(rest[2:], "*/")
			var seg string
			if end < 0 {
				seg = rest
				i = len(line)
			} else {
				seg = rest[:end+4]
				i += end + 4
			}
			out.WriteString(colItalic(73, seg))
			continue
		}
