			if lang == "json" {
				k := j
				for k < len(line) && line[k] == ' ' {
					k++
				}
				if k < len(line) && line[k] == ':' {
					out.WriteString(colBold(4, seg))
					i = j
					continue
				}
			}
			out.WriteString(col(61, seg))
			i = j
			continue
		}
		// numbers
		if c >= '0' && c <= '9' {
			j := i
			for j < len(line) && (isIdentChar(line[j]) || line[j] == '.') {
				j++
			}
			out.WriteString(col(71, line[i:j]))
			i = j
			continue
		}
