		}
		out.WriteByte(c)
		i++
	}
	return out.String()
}

func highlightMarkdown(line string) string {
	if strings.HasPrefix(line, "#") {
		return colBold(4, line)
	}
	var out strings.Builder
	i := 0
	for i < len(line) {
		if strings.HasPrefix(line[i:], "**") {
			end := strings.Index(line[i+2:], "**")
			if end >= 0 {
				seg := line[i : i+2+end+2]
				out.WriteString("\x1b[1m" + seg + "\x1b[0m\x1b[39m\x1b[49m")
				i += len(seg)
				continue
			}
		}
		if line[i] == '*' {
			end := strings.IndexByte(line[i+1:], '*')
			if end >= 0 {
				seg := line[i : i+1+end+1]
				out.WriteString("\x1b[3m" + seg + "\x1b[0m\x1b[39m\x1b[49m")
				i += len(seg)
				continue
			}
		}
		if line[i] == '`' {
			end := strings.IndexByte(line[i+1:], '`')
			if end >= 0 {
				seg := line[i : i+1+end+1]
				out.WriteString(col(61, seg))
				i += len(seg)
				continue
			}
		}
		out.WriteByte(line[i])
		i++
	}
	return out.String()
}
