func col(code int, s string) string { return "\x1b[38;5;" + itoa(code) + "m" + s + "\x1b[39m" }
func colBold(code int, s string) string {
	return "\x1b[1m\x1b[38;5;" + itoa(code) + "m" + s + "\x1b[0m\x1b[39m\x1b[49m"
}
func colItalic(code int, s string) string {
	return "\x1b[3m\x1b[38;5;" + itoa(code) + "m" + s + "\x1b[0m\x1b[39m\x1b[49m"
}
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var b [8]byte
	i := len(b)
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
