func isIdentChar(c byte) bool { return isIdentStart(c) || (c >= '0' && c <= '9') }

func highlightLine(line, lang string) string {
	if lang == "md" {
		return highlightMarkdown(line)
	}
	var out strings.Builder
	i := 0
	// whole-line comment handling for shell-like leading #!/ comments etc
	for i < len(line) {
		rest := line[i:]
		// comments
		if (lang == "python" || lang == "sh" || lang == "yaml" || lang == "toml" || lang == "generic") && strings.HasPrefix(rest, "#") {
			// A shebang line is entirely highlighted green in the original.
			if i == 0 && strings.HasPrefix(rest, "#!") {
				out.WriteString(col(2, rest))
			} else {
				out.WriteString(colItalic(73, rest))
			}
			break
		}
		if strings.HasPrefix(rest, "//") {
			out.WriteString(colItalic(73, rest))
			break
		}
		if strings.HasPrefix(rest, "/*") {
			end := strings.Index(rest[2:], "*/")
			var seg string
			if end < 0 {
				seg = rest
				i = len(line)
			} else {
				seg = rest[:end+4]
				i += end + 4
			}
			out.WriteString(colItalic(73, seg))
			continue
		}
		c := line[i]
		// strings
		if c == '"' || c == '\'' || c == '`' {
			j := i + 1
			for j < len(line) {
				if line[j] == '\\' && j+1 < len(line) {
					j += 2
					continue
				}
				if line[j] == c {
					j++
					break
				}
				j++
			}
			seg := line[i:j]
			// JSON keys are bold blue
			if lang == "json" {
				k := j
				for k < len(line) && line[k] == ' ' {
					k++
				}
				if k < len(line) && line[k] == ':' {
					out.WriteString(colBold(4, seg))
					i = j
					continue
				}
			}
			out.WriteString(col(61, seg))
			i = j
			continue
		}
		// numbers
		if c >= '0' && c <= '9' {
			j := i
			for j < len(line) && (isIdentChar(line[j]) || line[j] == '.') {
				j++
			}
			out.WriteString(col(71, line[i:j]))
			i = j
			continue
		}
		// identifiers / keywords
		if isIdentStart(c) {
			j := i
			for j < len(line) && isIdentChar(line[j]) {
				j++
			}
			word := line[i:j]
			lower := strings.ToLower(word)
			switch {
			case keywordsGeneric[lower] || keywordsGeneric[word]:
				out.WriteString(colBold(2, word))
			case lang == "json" && (word == "true" || word == "false" || word == "null"):
				out.WriteString(colBold(2, word))
			default:
				// a word followed by '(' is a function name in many languages
				k := j
				// peek
				if k < len(line) && line[k] == '(' {
					out.WriteString(col(4, word))
				} else if word == "print" || word == "echo" {
					out.WriteString(col(2, word))
				} else {
