			// slice or index
			var first *exprNode
			isSlice := false
			if !(p.peek().kind == tOp && p.peek().text == ":") {
				first, err = p.parseExpr()
				if err != nil {
					return nil, err
				}
			}
			var second *exprNode
			if p.peek().kind == tOp && p.peek().text == ":" {
				isSlice = true
				p.next()
				if !(p.peek().kind == tOp && (p.peek().text == "]" || p.peek().text == ":")) {
					second, err = p.parseExpr()
					if err != nil {
						return nil, err
					}
				}
				// optional second colon
				if p.peek().kind == tOp && p.peek().text == ":" {
					p.next()
					if !(p.peek().kind == tOp && p.peek().text == "]") {
						if _, err := p.parseExpr(); err != nil {
							return nil, err
						}
					}
				}
			}
			if _, err := p.expectOp("]"); err != nil {
				return nil, err
			}
			if isSlice {
				node = &exprNode{kind: nSlice, pos: pos, left: node, right: first, extra: second}
			} else {
				node = &exprNode{kind: nIndex, pos: pos, left: node, right: first}
			}
			continue
		}
		if t.kind == tOp && t.text == "(" {
			if node.kind == nCall {
				return nil, &exprError{msg: fmt.Sprintf("unexpected token Bracket(%q)", "("), pos: t.pos, src: p.src}
			}
			pos := t.pos
			p.next()
			var args []*exprNode
			// determine caller name for predicates
			caller := ""
			if node.kind == nIdent || node.kind == nMember {
				caller = node.name
			}
			if !(p.peek().kind == tOp && p.peek().text == ")") {
				for {
					argIdx := len(args)
					var arg *exprNode
					if predicateFuncs[caller] && argIdx >= 1 && p.peek().kind == tOp && p.peek().text == "{" {
						// closure
						p.next()
						inner, err := p.parseExpr()
						if err != nil {
							return nil, err
						}
						if _, err := p.expectOp("}"); err != nil {
							return nil, err
						}
						arg = &exprNode{kind: nClosure, pos: pos, left: inner}
					} else {
						arg, err = p.parseExpr()
						if err != nil {
							return nil, err
						}
					}
					args = append(args, arg)
					if p.peek().kind == tOp && p.peek().text == "," {
						p.next()
						continue
					}
					break
				}
			}
			if _, err := p.expectOp(")"); err != nil {
				return nil, err
			}
			node = &exprNode{kind: nCall, pos: pos, left: node, args: args}
			continue
		}
		break
	}
	return node, nil
}

func (p *parser) parsePrimary() (*exprNode, error) {
	t := p.peek()
	switch t.kind {
	case tHash:
		p.next()
		return &exprNode{kind: nHashVal, pos: t.pos}, nil
	case tNum:
		p.next()
		var v any
		if t.isF {
			v = t.numF
		} else {
			v = t.numI
		}
		return &exprNode{kind: nLit, pos: t.pos, value: v}, nil
	case tStr:
		p.next()
		return &exprNode{kind: nLit, pos: t.pos, value: t.str}, nil
	case tIdent:
		p.next()
		switch t.text {
		case "true":
			return &exprNode{kind: nLit, pos: t.pos, value: true}, nil
		case "false":
			return &exprNode{kind: nLit, pos: t.pos, value: false}, nil
		case "nil", "null":
			return &exprNode{kind: nLit, pos: t.pos, value: nil}, nil
		default:
			return &exprNode{kind: nIdent, pos: t.pos, name: t.text}, nil
		}
	case tOp:
		if t.text == "(" {
			p.next()
			v, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if _, err := p.expectOp(")"); err != nil {
				return nil, err
			}
			return v, nil
		}
		if t.text == "[" {
			pos := p.next().pos
			var elems []*exprNode
			if !(p.peek().kind == tOp && p.peek().text == "]") {
				for {
					e, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					elems = append(elems, e)
					if p.peek().kind == tOp && p.peek().text == "," {
						p.next()
						continue
					}
					break
				}
			}
			if _, err := p.expectOp("]"); err != nil {
				return nil, err
			}
			return &exprNode{kind: nArray, pos: pos, elems: elems}, nil
		}
		if t.text == "{" {
			pos := p.next().pos
			var keys, vals []*exprNode
			if !(p.peek().kind == tOp && p.peek().text == "}") {
				for {
					// closure body starting with # could be parsed as map? only reached for maps
					var key *exprNode
					kt := p.peek()
					if kt.kind == tIdent || kt.kind == tStr {
						p.next()
						var ks string
						if kt.kind == tStr {
							ks = kt.str
						} else {
							ks = kt.text
						}
						key = &exprNode{kind: nLit, pos: kt.pos, value: ks}
					} else {
						var err error
						key, err = p.parseExpr()
						if err != nil {
							return nil, err
						}
					}
					if _, err := p.expectOp(":"); err != nil {
						return nil, err
					}
					val, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					keys = append(keys, key)
					vals = append(vals, val)
					if p.peek().kind == tOp && p.peek().text == "," {
						p.next()
						continue
					}
					break
				}
			}
			if _, err := p.expectOp("}"); err != nil {
				return nil, err
			}
			return &exprNode{kind: nMap, pos: pos, keys: keys, elems: vals}, nil
		}
		if t.text == "-" || t.text == "!" {
			return p.parseUnary()
		}
	}
	if t.kind == tEOF {
		return nil, &exprError{msg: "unexpected token EOF", pos: len(p.src), src: p.src}
	}
	return nil, &exprError{msg: fmt.Sprintf("unexpected token %s", tokenName(t)), pos: t.pos, src: p.src}
}

// ---------------- type checking ----------------

type exprProgram struct {
	src  string
	root *exprNode
}

type typeInfo struct {
	kind string // string,int,float,bool,array,map,entry,fileinfo,filemode,time,any,func,nil
	elem *typeInfo
	name string
}

var (
	tyString = &typeInfo{kind: "string"}
	tyInt    = &typeInfo{kind: "int"}
	tyFloat  = &typeInfo{kind: "float"}
	tyBool   = &typeInfo{kind: "bool"}
	tyAny    = &typeInfo{kind: "any"}
	tyEntry  = &typeInfo{kind: "entry"}
	tyFInfo  = &typeInfo{kind: "fileinfo"}
	tyFMode  = &typeInfo{kind: "filemode"}
	tyTime   = &typeInfo{kind: "time"}
	tyNil    = &typeInfo{kind: "nil"}
)

func (t *typeInfo) String() string {
	if t == nil {
		return "interface {}"
	}
	switch t.kind {
	case "string":
		return "string"
	case "int":
		return "int"
	case "float":
		return "float64"
	case "bool":
		return "bool"
	case "array":
		if t.elem != nil {
			return "[]" + t.elem.String()
		}
		return "[]interface {}"
	case "map":
		return "map[string]interface {}"
	case "entry":
		return "fs.DirEntry"
	case "fileinfo":
		return "fs.FileInfo"
	case "filemode":
		return "fs.FileMode"
	case "time":
		return "time.Time"
	case "func":
		return "func"
	}
	return "interface {}"
}

func typeCategory(t *typeInfo) string {
	if t == nil {
		return "any"
	}
	switch t.kind {
	case "int", "float":
		return "number"
	case "string":
		return "string"
	case "bool":
		return "bool"
	case "array":
		return "array"
	case "map":
		return "map"
	}
	return "any"
}

var customFuncs = map[string]struct {
	min, max int
	ret      *typeInfo
	argTypes []*typeInfo // nil for variadic / unknown
}{
	"Mode":    {0, 0, tyString, nil},
	"Size":    {0, 0, tyString, nil},
	"Owner":   {0, 0, tyString, nil},
	"ModTime": {0, 0, tyString, nil},
	"PadLeft": {2, 2, tyString, []*typeInfo{tyString, tyInt}},
	"PadRight": {2, 2, tyString, []*typeInfo{tyString, tyInt}},
	"Sprintf": {1, 1 << 30, tyString, nil},
}

var builtinNames = map[string]bool{
	"len": true, "type": true, "string": true, "int": true, "float": true, "double": true,
	"any": true, "all": true, "none": true, "one": true, "map": true, "filter": true, "count": true,
	"find": true, "findIndex": true, "findLast": true, "findLastIndex": true,
	"join": true, "split": true, "splitAfter": true, "upper": true, "lower": true, "title": true,
	"trim": true, "trimPrefix": true, "trimSuffix": true, "repeat": true, "replace": true,
	"abs": true, "ceil": true, "floor": true, "round": true, "min": true, "max": true, "sum": true,
	"mean": true, "median": true, "keys": true, "values": true, "get": true, "has": true,
	"sort": true, "sortBy": true, "uniq": true, "unique": true, "reverse": true,
	"first": true, "last": true, "toJSON": true, "fromJSON": true, "toPairs": true, "fromPairs": true,
	"groupBy": true, "now": true, "duration": true, "date": true,
}

func (prog *statusProgram) check(n *exprNode) (*typeInfo, error) {
	if n == nil {
		return tyAny, nil
	}
	src := prog.src
	errf := func(msg string, pos int) error { return &exprError{msg: msg, pos: pos, src: src} }
	switch n.kind {
	case nLit:
		switch n.value.(type) {
		case string:
			return tyString, nil
		case int64:
			return tyInt, nil
		case float64:
			return tyFloat, nil
		case bool:
			return tyBool, nil
		case nil:
			return tyNil, nil
		}
		return tyAny, nil
	case nHashVal:
		return tyAny, nil
	case nIdent:
		switch n.name {
		case "current_file":
			return tyEntry, nil
		case "files":
			return &typeInfo{kind: "array", elem: tyEntry}, nil
		}
		if _, ok := customFuncs[n.name]; ok {
			return &typeInfo{kind: "func", name: n.name}, nil
		}
		if builtinNames[n.name] {
			return &typeInfo{kind: "func", name: n.name}, nil
		}
		if strings.HasPrefix(n.name, "$") {
			return tyAny, nil
		}
		return nil, errf(fmt.Sprintf("unknown name %s", n.name), n.pos)
	case nArray:
		var elem *typeInfo
		for _, e := range n.elems {
			t, err := prog.check(e)
			if err != nil {
				return nil, err
			}
			if elem == nil {
				elem = t
			} else if elem.kind != t.kind {
				elem = tyAny
			}
		}
		if elem == nil {
			elem = tyAny
		}
		return &typeInfo{kind: "array", elem: elem}, nil
	case nMap:
		for _, k := range n.keys {
			if _, err := prog.check(k); err != nil {
				return nil, err
			}
		}
		for _, v := range n.elems {
			if _, err := prog.check(v); err != nil {
				return nil, err
			}
		}
		return &typeInfo{kind: "map"}, nil
	case nClosure:
		return prog.check(n.left)
	case nLet:
		if _, err := prog.check(n.left); err != nil {
			return nil, err
		}
		return prog.check(n.right)
	case nMember:
		base, err := prog.check(n.left)
		if err != nil {
			return nil, err
		}
		if base.kind == "func" {
			// e.g. current_file.Info.Size - Info is a method value
			sig := "func() interface {}"
			if n.left.kind == nMember && n.left.name == "Info" {
				sig = "func() (fs.FileInfo, error)"
			}
			return nil, errf(fmt.Sprintf("type %s[string] is undefined", sig), n.pos)
		}
		if base.kind == "entry" {
			return &typeInfo{kind: "func", name: n.name}, nil
		}
		if base.kind == "fileinfo" {
			return &typeInfo{kind: "func", name: n.name}, nil
		}
		return tyAny, nil
	case nCall:
		// validate arguments first
		argTypes := make([]*typeInfo, len(n.args))
		for i, a := range n.args {
			t, err := prog.check(a)
			if err != nil {
				return nil, err
			}
			argTypes[i] = t
		}
		if n.left.kind == nIdent {
			name := n.left.name
			if cf, ok := customFuncs[name]; ok {
				if len(n.args) < cf.min {
					return nil, errf(fmt.Sprintf("not enough arguments to call %s", name), n.left.pos)
				}
				if len(n.args) > cf.max {
					return nil, errf(fmt.Sprintf("too many arguments to call %s", name), n.left.pos)
				}
				if cf.argTypes != nil {
					for i, want := range cf.argTypes {
						if i >= len(argTypes) {
							break
						}
						got := argTypes[i]
						if got.kind != "any" && got.kind != want.kind && !(want.kind == "string" && got.kind == "string") {
							// position of the offending argument
							return nil, errf(fmt.Sprintf("cannot use %s as argument (type %s) to call %s ", got.String(), want.String(), name), n.args[i].pos)
						}
					}
				}
				if name == "Sprintf" && len(argTypes) > 0 && argTypes[0].kind != "string" && argTypes[0].kind != "any" {
					return nil, errf(fmt.Sprintf("cannot use %s as argument (type string) to call Sprintf ", argTypes[0].String()), n.args[0].pos)
				}
				return cf.ret, nil
			}
			if name == "len" {
				if len(n.args) != 1 {
					return nil, errf(fmt.Sprintf("invalid number of arguments (expected 1, got %d)", len(n.args)), n.left.pos)
				}
				if len(argTypes) > 0 {
					c := typeCategory(argTypes[0])
					if c != "string" && c != "array" && c != "map" && c != "any" {
						return nil, errf(fmt.Sprintf("invalid argument for len (type %s)", argTypes[0].String()), n.left.pos)
					}
				}
				return tyInt, nil
			}
			if builtinNames[name] {
				return tyAny, nil
			}
			return nil, errf(fmt.Sprintf("unknown name %s", name), n.left.pos)
		}
		if n.left.kind == nMember {
			// check base
			if _, err := prog.check(n.left.left); err != nil {
				return nil, err
			}
			method := n.left.name
			base, _ := prog.check(n.left.left)
			// entry methods
			if base != nil && base.kind == "entry" {
				switch method {
				case "Name":
					if len(n.args) > 0 { return nil, errf("too many arguments to call Name", n.left.pos) }
					return tyString, nil
				case "IsDir":
					if len(n.args) > 0 { return nil, errf("too many arguments to call IsDir", n.left.pos) }
					return tyBool, nil
				case "Type":
					if len(n.args) > 0 { return nil, errf("too many arguments to call Type", n.left.pos) }
					return tyFMode, nil
				case "Info":
					if len(n.args) > 0 { return nil, errf("too many arguments to call Info", n.left.pos) }
					return tyFInfo, nil
				}
			}
			if base != nil && base.kind == "fileinfo" {
				switch method {
				case "Name": return tyString, nil
				case "Size": return tyInt, nil
				case "Mode": return tyFMode, nil
				case "ModTime": return tyTime, nil
				case "IsDir": return tyBool, nil
				case "Sys": return tyAny, nil
				}
			}
			if base != nil && base.kind == "filemode" && method == "String" {
				return tyString, nil
			}
			return tyAny, nil
		}
		if _, err := prog.check(n.left); err != nil {
			return nil, err
		}
		return tyAny, nil
	case nIndex:
		base, err := prog.check(n.left)
		if err != nil {
			return nil, err
		}
		idx, err := prog.check(n.right)
		if err != nil {
			return nil, err
		}
		if base.kind == "array" {
			if idx.kind != "int" && idx.kind != "any" {
				return nil, errf(fmt.Sprintf("array elements can only be selected using an integer (got %s)", idx.String()), n.pos)
			}
			return base.elem, nil
		}
		if base.kind == "string" {
			return nil, errf(fmt.Sprintf("type string[%s] is undefined", idx.String()), n.pos)
		}
		if base.kind == "map" {
			return tyAny, nil
		}
		return tyAny, nil
	case nSlice:
		base, err := prog.check(n.left)
		if err != nil {
			return nil, err
		}
		if n.right != nil {
			if _, err := prog.check(n.right); err != nil { return nil, err }
		}
		if n.extra != nil {
			if _, err := prog.check(n.extra); err != nil { return nil, err }
		}
		return base, nil
	case nUnary:
		t, err := prog.check(n.left)
		if err != nil {
			return nil, err
		}
		if n.op == "!" || n.op == "not" {
			return tyBool, nil
		}
		return t, nil
	case nCond:
		if _, err := prog.check(n.left); err != nil { return nil, err }
		a, err := prog.check(n.right)
		if err != nil { return nil, err }
		if _, err := prog.check(n.extra); err != nil { return nil, err }
		return a, nil
	case nBinary:
		if n.op == "|" {
			if _, err := prog.check(n.left); err != nil { return nil, err }
			return prog.check(n.right)
		}
		lt, err := prog.check(n.left)
		if err != nil {
			return nil, err
		}
		rt, err := prog.check(n.right)
		if err != nil {
			return nil, err
		}
		lc, rc := typeCategory(lt), typeCategory(rt)
		mismatch := func() error {
			return errf(fmt.Sprintf("invalid operation: %s (mismatched types %s and %s)", n.op, lt.String(), rt.String()), n.pos)
		}
		switch n.op {
		case "+":
			if lc == "string" && rc == "string" { return tyString, nil }
			if lc == "number" && rc == "number" {
				if lt.kind == "float" || rt.kind == "float" { return tyFloat, nil }
				return tyInt, nil
			}
			if lc == "array" && rc == "array" { return lt, nil }
			if lc == "any" || rc == "any" { return tyAny, nil }
			if lc == "nil" || rc == "nil" { return tyAny, nil }
			return nil, mismatch()
		case "-", "*":
			if lc == "number" && rc == "number" {
				if lt.kind == "float" || rt.kind == "float" { return tyFloat, nil }
				return tyInt, nil
			}
			if lc == "any" || rc == "any" { return tyAny, nil }
			return nil, mismatch()
		case "/":
			if lc == "number" && rc == "number" { return tyFloat, nil }
			if lc == "any" || rc == "any" { return tyAny, nil }
			return nil, mismatch()
		case "%":
			// constant integer divide by zero is a compile-time error in the original
			if n.left.kind == nLit && n.right.kind == nLit {
				if rv, ok := n.right.value.(int64); ok && rv == 0 {
					return nil, errf("integer divide by zero", n.pos)
				}
			}
			if lc == "number" && rc == "number" { return tyInt, nil }
			if lc == "any" || rc == "any" { return tyAny, nil }
			return nil, mismatch()
		case "**":
			if lc == "number" && rc == "number" { return tyFloat, nil }
			if lc == "any" || rc == "any" { return tyAny, nil }
			return nil, mismatch()
		case "&&", "||", "and", "or":
			if (lc == "bool" || lc == "any") && (rc == "bool" || rc == "any") { return tyBool, nil }
			return nil, mismatch()
		case "==", "!=":
			return tyBool, nil
		case "<", "<=", ">", ">=":
			if lc == rc && (lc == "number" || lc == "string" || lc == "any") { return tyBool, nil }
			if lc == "any" || rc == "any" { return tyBool, nil }
			return nil, mismatch()
		case "..":
			if lc == "number" && rc == "number" && lt.kind != "float" && rt.kind != "float" { return &typeInfo{kind: "array", elem: tyInt}, nil }
			if lc == "any" || rc == "any" { return tyAny, nil }
			return nil, mismatch()
		case "in", "contains", "startsWith", "endsWith", "matches":
			return tyBool, nil
		case "??":
			return lt, nil
		}
		return tyAny, nil
	}
	return tyAny, nil
}

// ---------------- evaluation ----------------

type statusProgram struct {
	src  string
	root *exprNode
}

type funcValue struct {
	name string
	fn   func(env *evalEnv, args []any) (any, error)
}

type evalEnv struct {
	model *model
	vars  map[string]any
}

func (prog *statusProgram) run(m *model) (any, error) {
	env := &evalEnv{model: m, vars: map[string]any{}}
	return prog.eval(prog.root, env)
}

func (prog *statusProgram) evalErr(msg string, pos int) error {
	return &exprError{msg: msg, pos: pos, src: prog.src}
}

func isNumber(v any) (float64, bool) {
	switch x := v.(type) {
	case int64:
		return float64(x), true
	case int:
		return float64(x), true
	case int32:
		return float64(x), true
	case uint64:
		return float64(x), true
	case float64:
		return x, true
	case float32:
		return float64(x), true
	}
	return 0, false
}
func isIntVal(v any) (int64, bool) {
	switch x := v.(type) {
	case int64:
		return x, true
	case int:
		return int64(x), true
	case int32:
		return int64(x), true
	}
	return 0, false
}

func (prog *statusProgram) eval(n *exprNode, env *evalEnv) (any, error) {
	switch n.kind {
	case nLit:
		return n.value, nil
	case nHashVal:
		if v, ok := env.vars["#"]; ok {
			return v, nil
		}
		return nil, nil
	case nIdent:
		switch n.name {
		case "current_file":
			if f := env.model.currentEntry(); f != nil {
				return entryValue{e: f.DirEntry}, nil
			}
			return nil, nil
		case "files":
			files := env.model.files
			out := make([]entryValue, len(files))
			for i, f := range files {
				out[i] = entryValue{e: f.DirEntry}
			}
			return out, nil
		}
		if v, ok := env.vars[n.name]; ok {
			return v, nil
		}
		if _, ok := customFuncs[n.name]; ok {
			name := n.name
			return &funcValue{name: name, fn: func(env *evalEnv, args []any) (any, error) {
				return env.model.callStatusFunc(name, args)
			}}, nil
		}
		if builtinNames[n.name] {
			return nil, prog.evalErr(fmt.Sprintf("cannot fetch %s from main.Env", n.name), n.pos)
		}
		if strings.HasPrefix(n.name, "$") {
			if v, ok := env.vars[n.name]; ok {
				return v, nil
			}
			return nil, nil
		}
		return nil, prog.evalErr(fmt.Sprintf("unknown name %s", n.name), n.pos)
	case nLet:
		v, err := prog.eval(n.left, env)
		if err != nil {
			return nil, err
		}
		old, had := env.vars[n.name]
		env.vars[n.name] = v
		defer func() {
			if had { env.vars[n.name] = old } else { delete(env.vars, n.name) }
		}()
		return prog.eval(n.right, env)
	case nArray:
		out := make([]any, len(n.elems))
		for i, e := range n.elems {
			v, err := prog.eval(e, env)
			if err != nil {
				return nil, err
			}
			out[i] = v
		}
		return out, nil
	case nMap:
		out := make(map[string]any)
		for i, k := range n.keys {
			kv, err := prog.eval(k, env)
			if err != nil {
				return nil, err
			}
			v, err := prog.eval(n.elems[i], env)
			if err != nil {
				return nil, err
			}
			out[fmt.Sprint(kv)] = v
		}
		return out, nil
	case nClosure:
		return prog.eval(n.left, env)
	case nMember:
		base, err := prog.eval(n.left, env)
		if err != nil {
			return nil, err
		}
		return prog.member(base, n.name, n.pos)
	case nIndex:
		base, err := prog.eval(n.left, env)
		if err != nil {
			return nil, err
		}
		idx, err := prog.eval(n.right, env)
		if err != nil {
			return nil, err
		}
		return prog.index(base, idx, n.pos)
	case nSlice:
		base, err := prog.eval(n.left, env)
		if err != nil {
			return nil, err
		}
		var lo, hi *int64
		if n.right != nil {
			v, err := prog.eval(n.right, env)
			if err != nil { return nil, err }
			if iv, ok := isIntVal(v); ok { lo = &iv }
		}
		if n.extra != nil {
			v, err := prog.eval(n.extra, env)
			if err != nil { return nil, err }
			if iv, ok := isIntVal(v); ok { hi = &iv }
		}
		return sliceValue(base, lo, hi)
	case nUnary:
		v, err := prog.eval(n.left, env)
		if err != nil {
			return nil, err
		}
		switch n.op {
		case "!":
			if b, ok := v.(bool); ok { return !b, nil }
			return nil, prog.evalErr("invalid operation: !", n.pos)
		case "not":
			if b, ok := v.(bool); ok { return !b, nil }
			return nil, nil
		case "-":
			if iv, ok := isIntVal(v); ok { return -iv, nil }
			if fv, ok := isNumber(v); ok { return -fv, nil }
			return nil, nil
		case "+":
			return v, nil
		}
		return v, nil
	case nCond:
		c, err := prog.eval(n.left, env)
		if err != nil {
			return nil, err
		}
		if b, ok := c.(bool); ok && b {
			return prog.eval(n.right, env)
		}
		if c != nil && c != false {
			// expr treats truthiness? conditional requires bool; approximate
			return prog.eval(n.right, env)
		}
		return prog.eval(n.extra, env)
	case nBinary:
		return prog.evalBinary(n, env)
	case nCall:
		return prog.evalCall(n, env)
	}
	return nil, nil
}

func sliceValue(base any, lo, hi *int64) (any, error) {
	rv := reflect.ValueOf(base)
	if rv.Kind() == reflect.String {
		s := base.(string)
		r := []rune(s)
		l, h := sliceBounds(len(r), lo, hi)
		return string(r[l:h]), nil
	}
	if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
		l, h := sliceBounds(rv.Len(), lo, hi)
		out := rv.Slice(l, h)
		return out.Interface(), nil
	}
	return base, nil
}
func sliceBounds(length int, lo, hi *int64) (int, int) {
	l := 0
	if lo != nil {
		l = int(*lo)
		if l < 0 { l = length + l }
	}
	h := length
	if hi != nil {
		h = int(*hi)
		if h < 0 { h = length + h }
	}
	if l < 0 { l = 0 }
	if l > length { l = length }
	if h < l { h = l }
	if h > length { h = length }
	return l, h
}

func (prog *statusProgram) index(base, idx any, pos int) (any, error) {
	if m, ok := base.(map[string]any); ok {
		return m[fmt.Sprint(idx)], nil
	}
	rv := reflect.ValueOf(base)
	if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
		iv, ok := isIntVal(idx)
		if !ok {
			if fv, ok2 := isNumber(idx); ok2 { iv = int64(fv); ok = true }
		}
		if !ok {
			return nil, prog.evalErr(fmt.Sprintf("array elements can only be selected using an integer (got %T)", idx), pos)
		}
		i := int(iv)
		if i < 0 {
			i = rv.Len() + i
		}
		if i < 0 || i >= rv.Len() {
			return nil, prog.evalErr(fmt.Sprintf("index out of range: %d (array length is %d)", iv, rv.Len()), pos)
		}
		return rv.Index(i).Interface(), nil
	}
	if s, ok := base.(string); ok {
		_ = s
		return nil, prog.evalErr("type string[int] is undefined", pos)
	}
	if base == nil {
		return nil, nil
	}
	return nil, nil
}

func (prog *statusProgram) member(base any, name string, pos int) (any, error) {
	if base == nil {
		return nil, nil
	}
	if m, ok := base.(map[string]any); ok {
		return m[name], nil
	}
	// entry / fileInfo methods are returned as callable values
	switch v := base.(type) {
	case entryValue:
		return &funcValue{name: name, fn: func(env *evalEnv, args []any) (any, error) {
			return callEntryMethod(v, name, args)
		}}, nil
	case fileInfoValue:
		return &funcValue{name: name, fn: func(env *evalEnv, args []any) (any, error) {
			return callFileInfoMethod(v, name, args)
		}}, nil
	}
	// reflection for methods/fields on other values
	rv := reflect.ValueOf(base)
	if rv.IsValid() {
		if m := rv.MethodByName(name); m.IsValid() {
			return &funcValue{name: name, fn: func(env *evalEnv, args []any) (any, error) {
				return callReflectMethod(rv, name, args)
			}}, nil
		}
		if rv.Kind() == reflect.Struct {
			if f := rv.FieldByName(name); f.IsValid() {
				return f.Interface(), nil
			}
		}
		if rv.Kind() == reflect.Ptr && !rv.IsNil() {
			if f := rv.Elem().FieldByName(name); f.IsValid() {
				return f.Interface(), nil
			}
		}
		// property access on a slice applies to ... return a function placeholder
		if rv.Kind() == reflect.Slice {
			return &funcValue{name: name, fn: func(env *evalEnv, args []any) (any, error) { return nil, nil }}, nil
		}
	}
	return nil, nil
}

func callReflectMethod(rv reflect.Value, name string, args []any) (any, error) {
	m := rv.MethodByName(name)
	if !m.IsValid() {
		return nil, nil
	}
	in := make([]reflect.Value, len(args))
	mt := m.Type()
	for i, a := range args {
		if i >= mt.NumIn() {
			break
		}
		want := mt.In(i)
		if a == nil {
			in[i] = reflect.Zero(want)
		} else if reflect.TypeOf(a).AssignableTo(want) {
			in[i] = reflect.ValueOf(a)
		} else if fv, ok := isNumber(a); ok && want.Kind() >= reflect.Int && want.Kind() <= reflect.Float64 {
			in[i] = reflect.ValueOf(fv).Convert(want)
		} else {
			in[i] = reflect.ValueOf(fmt.Sprint(a)).Convert(want)
		}
	}
	// pad missing
	if len(args) < mt.NumIn() && !mt.IsVariadic() {
		for len(in) < mt.NumIn() {
			in = append(in, reflect.Zero(mt.In(len(in))))
		}
	}
	out := m.Call(in)
	if len(out) == 0 {
		return nil, nil
	}
	if len(out) == 2 {
		if !out[1].IsNil() {
			if err, ok := out[1].Interface().(error); ok {
				return nil, err
			}
		}
		return out[0].Interface(), nil
	}
	return out[0].Interface(), nil
}

func (prog *statusProgram) evalCall(n *exprNode, env *evalEnv) (any, error) {
	// method call
	if n.left.kind == nMember {
		base, err := prog.eval(n.left.left, env)
		if err != nil {
			return nil, err
		}
		args := make([]any, len(n.args))
		for i, a := range n.args {
			v, err := prog.eval(a, env)
			if err != nil {
				return nil, err
			}
			args[i] = v
		}
		return callMethodValue(base, n.left.name, args, prog, n.left.pos)
	}
	if n.left.kind == nIdent {
		name := n.left.name
		// predicate builtins are lazy
		if predicateFuncs[name] {
			return prog.evalPredicateBuiltin(name, n, env)
		}
		args := make([]any, len(n.args))
		for i, a := range n.args {
			v, err := prog.eval(a, env)
			if err != nil {
				return nil, err
			}
			args[i] = v
		}
		if _, ok := customFuncs[name]; ok {
			return env.model.callStatusFunc(name, args)
		}
		return callBuiltin(name, args, prog, n.left.pos)
	}
	// call a value
	callee, err := prog.eval(n.left, env)
	if err != nil {
		return nil, err
	}
	args := make([]any, len(n.args))
	for i, a := range n.args {
		v, err := prog.eval(a, env)
		if err != nil {
			return nil, err
		}
		args[i] = v
	}
	if fv, ok := callee.(*funcValue); ok {
		return fv.fn(env, args)
	}
	return nil, nil
}

func callMethodValue(base any, name string, args []any, prog *statusProgram, pos int) (any, error) {
	switch v := base.(type) {
	case entryValue:
		return callEntryMethod(v, name, args)
	case fileInfoValue:
		return callFileInfoMethod(v, name, args)
	}
	if base == nil {
		return nil, nil
	}
	rv := reflect.ValueOf(base)
	if rv.IsValid() && rv.MethodByName(name).IsValid() {
		return callReflectMethod(rv, name, args)
	}
	return nil, nil
}

func (prog *statusProgram) evalPredicateBuiltin(name string, n *exprNode, env *evalEnv) (any, error) {
	if len(n.args) == 0 {
		return nil, nil
	}
	coll, err := prog.eval(n.args[0], env)
	if err != nil {
		return nil, err
	}
	items := toAnySlice(coll)
	if items == nil {
		// mapping over a map etc.
		return nil, nil
	}
	var pred *exprNode
	if len(n.args) > 1 {
		pred = n.args[1]
	}
	evalPred := func(item any, idx int) (any, error) {
		old, had := env.vars["#"]
		oldAcc, hadAcc := env.vars["$acc"]
		env.vars["#"] = item
		_ = oldAcc
		_ = hadAcc
		defer func() {
			if had { env.vars["#"] = old } else { delete(env.vars, "#") }
		}()
		if pred == nil {
			return item, nil
		}
		if pred.kind == nClosure {
			return prog.eval(pred.left, env)
		}
		return prog.eval(pred, env)
	}
	switch name {
	case "map":
		out := make([]any, len(items))
		for i, it := range items {
			v, err := evalPred(it, i)
			if err != nil { return nil, err }
			out[i] = v
		}
		return out, nil
	case "filter":
		var out []any
		for i, it := range items {
			v, err := evalPred(it, i)
			if err != nil { return nil, err }
			if truthy(v) { out = append(out, it) }
		}
		if out == nil { out = []any{} }
		return out, nil
	case "any":
		for i, it := range items {
			v, err := evalPred(it, i)
			if err != nil { return nil, err }
			if truthy(v) { return true, nil }
		}
		return false, nil
	case "all":
		for i, it := range items {
			v, err := evalPred(it, i)
			if err != nil { return nil, err }
			if !truthy(v) { return false, nil }
		}
		return true, nil
	case "none":
		for i, it := range items {
			v, err := evalPred(it, i)
			if err != nil { return nil, err }
			if truthy(v) { return false, nil }
		}
		return true, nil
	case "count":
		if pred == nil { return int64(len(items)), nil }
		c := int64(0)
		for i, it := range items {
			v, err := evalPred(it, i)
			if err != nil { return nil, err }
			if truthy(v) { c++ }
		}
		return c, nil
	case "find":
		for i, it := range items {
			v, err := evalPred(it, i)
			if err != nil { return nil, err }
			if truthy(v) { return it, nil }
		}
		return nil, nil
	case "findIndex":
		for i, it := range items {
			v, err := evalPred(it, i)
			if err != nil { return nil, err }
			if truthy(v) { return int64(i), nil }
		}
		return int64(-1), nil
	case "one":
		c := 0
		for i, it := range items {
			v, err := evalPred(it, i)
			if err != nil { return nil, err }
			if truthy(v) { c++ }
		}
		return c == 1, nil
	}
	// groupBy / sortBy - approximate
	if name == "sortBy" {
		type pair struct { item, key any }
		pairs := make([]pair, len(items))
		for i, it := range items {
			v, err := evalPred(it, i)
			if err != nil { return nil, err }
			pairs[i] = pair{it, v}
		}
		sort.SliceStable(pairs, func(a, b int) bool { return fmt.Sprint(pairs[a].key) < fmt.Sprint(pairs[b].key) })
		out := make([]any, len(pairs))
		for i, p := range pairs { out[i] = p.item }
		return out, nil
	}
	if name == "groupBy" {
		out := make(map[string]any)
		for i, it := range items {
			v, err := evalPred(it, i)
			if err != nil { return nil, err }
			k := fmt.Sprint(v)
			if cur, ok := out[k].([]any); ok { out[k] = append(cur, it) } else { out[k] = []any{it} }
		}
		return out, nil
	}
	return nil, nil
}

func truthy(v any) bool {
	if b, ok := v.(bool); ok { return b }
	if v == nil { return false }
	return true
}

func toAnySlice(v any) []any {
	if v == nil { return nil }
	if s, ok := v.([]any); ok { return s }
	rv := reflect.ValueOf(v)
	if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
		out := make([]any, rv.Len())
		for i := 0; i < rv.Len(); i++ { out[i] = rv.Index(i).Interface() }
		return out
	}
	if s, ok := v.(string); ok {
		out := make([]any, 0)
		for _, r := range s { out = append(out, string(r)) }
		return out
	}
	return nil
}

func (prog *statusProgram) evalBinary(n *exprNode, env *evalEnv) (any, error) {
	if n.op == "|" {
		left, err := prog.eval(n.left, env)
		if err != nil { return nil, err }
		// rewrite right as call with left prepended
		if n.right.kind == nCall {
			call := *n.right
			args := []*exprNode{{kind: nLit, value: left}}
			// we cannot easily inject a literal for arbitrary values via node:
			// evaluate manually here
			if call.left.kind == nIdent {
				name := call.left.name
				if predicateFuncs[name] {
					// unlikely
				}
				argv := []any{left}
				for _, a := range call.args {
					v, err := prog.eval(a, env)
					if err != nil { return nil, err }
					argv = append(argv, v)
				}
				if _, ok := customFuncs[name]; ok {
					return env.model.callStatusFunc(name, argv)
				}
				return callBuiltin(name, argv, prog, call.left.pos)
			}
			if call.left.kind == nMember {
				// method on left?
				argv := []any{}
				for _, a := range call.args {
					v, err := prog.eval(a, env)
					if err != nil { return nil, err }
					argv = append(argv, v)
				}
				_ = args
				return callMethodValue(left, call.left.name, argv, prog, call.left.pos)
			}
			// generic call value
			callee, err := prog.eval(call.left, env)
			if err != nil { return nil, err }
			argv := []any{left}
			for _, a := range call.args {
				v, err := prog.eval(a, env)
				if err != nil { return nil, err }
				argv = append(argv, v)
			}
			if fv, ok := callee.(*funcValue); ok { return fv.fn(env, argv) }
			return nil, nil
		}
		if n.right.kind == nIdent {
			name := n.right.name
			if _, ok := customFuncs[name]; ok {
				return env.model.callStatusFunc(name, []any{left})
			}
			return callBuiltin(name, []any{left}, prog, n.right.pos)
		}
		// pipe to a non-call expression: evaluate with # ? just evaluate right
		return prog.eval(n.right, env)
	}
	// short circuit
	if n.op == "&&" || n.op == "and" {
		l, err := prog.eval(n.left, env)
		if err != nil { return nil, err }
		if b, ok := l.(bool); ok && !b { return false, nil }
		r, err := prog.eval(n.right, env)
		if err != nil { return nil, err }
		lb, _ := l.(bool); rb, _ := r.(bool)
		return lb && rb, nil
	}
	if n.op == "||" || n.op == "or" {
		l, err := prog.eval(n.left, env)
		if err != nil { return nil, err }
		if b, ok := l.(bool); ok && b { return true, nil }
		r, err := prog.eval(n.right, env)
		if err != nil { return nil, err }
		lb, _ := l.(bool); rb, _ := r.(bool)
		return lb || rb, nil
	}
	l, err := prog.eval(n.left, env)
	if err != nil { return nil, err }
	r, err := prog.eval(n.right, env)
	if err != nil { return nil, err }
	switch n.op {
	case "??":
		if l == nil { return r, nil }
		return l, nil
	case "+":
		if ls, ok := l.(string); ok {
			if rs, ok := r.(string); ok { return ls + rs, nil }
		}
		if la := toAnySlice(l); la != nil {
			if ra := toAnySlice(r); ra != nil { return append(la, ra...), nil }
		}
		if li, ok := isIntVal(l); ok {
			if ri, ok := isIntVal(r); ok { return li + ri, nil }
		}
		if lf, ok := isNumber(l); ok {
			if rf, ok := isNumber(r); ok { return lf + rf, nil }
		}
		return nil, prog.evalErr(fmt.Sprintf("invalid operation: + (mismatched types %T and %T)", l, r), n.pos)
	case "-":
		if li, ok := isIntVal(l); ok { if ri, ok := isIntVal(r); ok { return li - ri, nil } }
		if lf, ok := isNumber(l); ok { if rf, ok := isNumber(r); ok { return lf - rf, nil } }
	case "*":
		if li, ok := isIntVal(l); ok { if ri, ok := isIntVal(r); ok { return li * ri, nil } }
		if lf, ok := isNumber(l); ok { if rf, ok := isNumber(r); ok { return lf * rf, nil } }
	case "/":
		if lf, ok := isNumber(l); ok { if rf, ok := isNumber(r); ok { return lf / rf, nil } }
	case "%":
		if li, ok := isIntVal(l); ok { if ri, ok := isIntVal(r); ok {
			if ri == 0 { return nil, prog.evalErr("integer divide by zero", n.pos) }
			return li % ri, nil } }
		if lf, ok := isNumber(l); ok { if rf, ok := isNumber(r); ok { return math.Mod(lf, rf), nil } }
	case "**":
		if lf, ok := isNumber(l); ok { if rf, ok := isNumber(r); ok { return math.Pow(lf, rf), nil } }
	case "==":
		return valuesEqual(l, r), nil
	case "!=":
		return !valuesEqual(l, r), nil
	case "<", "<=", ">", ">=":
		if lf, ok := isNumber(l); ok { if rf, ok := isNumber(r); ok {
			switch n.op { case "<": return lf < rf, nil; case "<=": return lf <= rf, nil; case ">": return lf > rf, nil; case ">=": return lf >= rf, nil }
		} }
		if ls, ok := l.(string); ok { if rs, ok := r.(string); ok {
			switch n.op { case "<": return ls < rs, nil; case "<=": return ls <= rs, nil; case ">": return ls > rs, nil; case ">=": return ls >= rs, nil }
		} }
	case "..":
		if li, ok := isIntVal(l); ok { if ri, ok := isIntVal(r); ok {
			var out []any
			for i := li; i <= ri; i++ { out = append(out, i) }
			if out == nil { out = []any{} }
			return out, nil
		} }
	case "in":
		if arr := toAnySlice(r); arr != nil {
			for _, e := range arr { if valuesEqual(l, e) { return true, nil } }
			return false, nil
		}
		if m, ok := r.(map[string]any); ok { _, ok2 := m[fmt.Sprint(l)]; return ok2, nil }
		if rs, ok := r.(string); ok { if ls, ok := l.(string); ok { return strings.Contains(rs, ls), nil } }
		return false, nil
	case "contains":
		if ls, ok := l.(string); ok { if rs, ok := r.(string); ok { return strings.Contains(ls, rs), nil } }
		if arr := toAnySlice(l); arr != nil { for _, e := range arr { if valuesEqual(e, r) { return true, nil } }; return false, nil }
	case "startsWith":
		if ls, ok := l.(string); ok { if rs, ok := r.(string); ok { return strings.HasPrefix(ls, rs), nil } }
	case "endsWith":
		if ls, ok := l.(string); ok { if rs, ok := r.(string); ok { return strings.HasSuffix(ls, rs), nil } }
	case "matches":
		if ls, ok := l.(string); ok { if rs, ok := r.(string); ok {
			re, err := regexp.Compile(rs); if err != nil { return nil, err }; return re.MatchString(ls), nil } }
	}
	return nil, nil
}

func valuesEqual(a, b any) bool {
	if af, ok := isNumber(a); ok {
		if bf, ok := isNumber(b); ok { return af == bf }
	}
	return reflect.DeepEqual(a, b)
}

// ---------------- builtins ----------------

func callBuiltin(name string, args []any, prog *statusProgram, pos int) (any, error) {
	errf := func(msg string) error { return prog.evalErr(msg, pos) }
	switch name {
	case "len":
		if len(args) != 1 { return nil, errf(fmt.Sprintf("invalid number of arguments (expected 1, got %d)", len(args))) }
		switch v := args[0].(type) {
		case string:
			return int64(utf8.RuneCountInString(v)), nil
		}
		if s := toAnySlice(args[0]); s != nil { return int64(len(s)), nil }
		if m, ok := args[0].(map[string]any); ok { return int64(len(m)), nil }
		rv := reflect.ValueOf(args[0])
		if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array || rv.Kind() == reflect.Map { return int64(rv.Len()), nil }
		return nil, errf(fmt.Sprintf("invalid argument for len (type %T)", args[0]))
	case "string":
		if len(args) == 0 { return "", nil }
		return formatExprValue(args[0]), nil
	case "int":
		if len(args) == 0 { return int64(0), nil }
		if f, ok := isNumber(args[0]); ok { return int64(f), nil }
		if s, ok := args[0].(string); ok { v, _ := strconv.ParseInt(strings.TrimSpace(s), 10, 64); return v, nil }
		if b, ok := args[0].(bool); ok { if b { return int64(1), nil }; return int64(0), nil }
		return int64(0), nil
	case "float", "double":
		if len(args) == 0 { return float64(0), nil }
		if f, ok := isNumber(args[0]); ok { return f, nil }
		if s, ok := args[0].(string); ok { v, _ := strconv.ParseFloat(strings.TrimSpace(s), 64); return v, nil }
		return float64(0), nil
	case "type":
		if len(args) == 0 { return "nil", nil }
		switch args[0].(type) {
		case string: return "string", nil
		case int64, int: return "int", nil
		case float64: return "float64", nil
		case bool: return "bool", nil
		case nil: return "nil", nil
		}
		if toAnySlice(args[0]) != nil { return "array", nil }
		if _, ok := args[0].(map[string]any); ok { return "map", nil }
		return fmt.Sprintf("%T", args[0]), nil
	case "join":
		if len(args) == 0 { return "", nil }
		// join(array, sep) or join(array)
		var arr []any; sep := ""
		if len(args) >= 1 { arr = toAnySlice(args[0]) }
		if arr == nil {
			// array is pipe-provided as first arg in our rewrite; if first arg is string (sep) ??? (when used as ["a"] | join, arr is array)
			return "", nil
		}
		if len(args) >= 2 { sep = fmt.Sprint(args[1]) }
		parts := make([]string, len(arr))
		for i, e := range arr { parts[i] = formatExprValue(e) }
		return strings.Join(parts, sep), nil
	case "split":
		if len(args) >= 2 { parts := strings.Split(fmt.Sprint(args[0]), fmt.Sprint(args[1])); out := make([]any, len(parts)); for i, p := range parts { out[i] = p }; return out, nil }
		if len(args) == 1 { parts := strings.Fields(fmt.Sprint(args[0])); out := make([]any, len(parts)); for i, p := range parts { out[i] = p }; return out, nil }
	case "splitAfter":
		if len(args) >= 2 { parts := strings.SplitAfter(fmt.Sprint(args[0]), fmt.Sprint(args[1])); out := make([]any, len(parts)); for i, p := range parts { out[i] = p }; return out, nil }
	case "upper":
		if len(args) > 0 { return strings.ToUpper(fmt.Sprint(args[0])), nil }
	case "lower":
		if len(args) > 0 { return strings.ToLower(fmt.Sprint(args[0])), nil }
	case "title":
		if len(args) > 0 { return strings.Title(fmt.Sprint(args[0])), nil }
	case "trim":
		if len(args) >= 2 { return strings.Trim(fmt.Sprint(args[0]), fmt.Sprint(args[1])), nil }
		if len(args) == 1 { return strings.TrimSpace(fmt.Sprint(args[0])), nil }
	case "trimPrefix":
		if len(args) >= 2 { return strings.TrimPrefix(fmt.Sprint(args[0]), fmt.Sprint(args[1])), nil }
	case "trimSuffix":
		if len(args) >= 2 { return strings.TrimSuffix(fmt.Sprint(args[0]), fmt.Sprint(args[1])), nil }
	case "repeat":
		if len(args) >= 2 { c, _ := isIntVal(args[1]); if c < 0 { c = 0 }; return strings.Repeat(fmt.Sprint(args[0]), int(c)), nil }
	case "replace":
		if len(args) >= 3 { return strings.ReplaceAll(fmt.Sprint(args[0]), fmt.Sprint(args[1]), fmt.Sprint(args[2])), nil }
	case "abs":
		if len(args) > 0 { if f, ok := isNumber(args[0]); ok { return math.Abs(f), nil } }
	case "ceil":
		if len(args) > 0 { if f, ok := isNumber(args[0]); ok { return math.Ceil(f), nil } }
	case "floor":
		if len(args) > 0 { if f, ok := isNumber(args[0]); ok { return math.Floor(f), nil } }
	case "round":
		if len(args) > 0 { if f, ok := isNumber(args[0]); ok { return math.Round(f), nil } }
	case "min", "max":
		var vals []any
		if len(args) == 1 { vals = toAnySlice(args[0]) } else { vals = args }
		if len(vals) == 0 { return nil, nil }
		best := vals[0]; bf, _ := isNumber(best)
		for _, v := range vals[1:] { f, _ := isNumber(v); if (name == "min" && f < bf) || (name == "max" && f > bf) { best, bf = v, f } }
		return best, nil
	case "sum":
		var vals []any
		if len(args) == 1 { vals = toAnySlice(args[0]) } else { vals = args }
		sum := 0.0; allInt := true
		for _, v := range vals { f, _ := isNumber(v); sum += f; if _, ok := isIntVal(v); !ok { allInt = false } }
		if allInt { return int64(sum), nil }
		return sum, nil
	case "mean":
		var vals []any
		if len(args) == 1 { vals = toAnySlice(args[0]) } else { vals = args }
		if len(vals) == 0 { return float64(0), nil }
		sum := 0.0; for _, v := range vals { f, _ := isNumber(v); sum += f }; return sum / float64(len(vals)), nil
	case "keys":
		if len(args) > 0 { if m, ok := args[0].(map[string]any); ok { ks := make([]string, 0); for k := range m { ks = append(ks, k) }; sort.Strings(ks); out := make([]any, len(ks)); for i, k := range ks { out[i] = k }; return out, nil } }
	case "values":
		if len(args) > 0 { if m, ok := args[0].(map[string]any); ok { ks := make([]string, 0); for k := range m { ks = append(ks, k) }; sort.Strings(ks); out := make([]any, len(ks)); for i, k := range ks { out[i] = m[k] }; return out, nil } }
	case "get":
		if len(args) >= 2 {
			if arr := toAnySlice(args[0]); arr != nil { if iv, ok := isIntVal(args[1]); ok && int(iv) >= 0 && int(iv) < len(arr) { return arr[iv], nil }; if len(args) >= 3 { return args[2], nil }; return nil, nil }
			if m, ok := args[0].(map[string]any); ok { if v, ok := m[fmt.Sprint(args[1])]; ok { return v, nil }; if len(args) >= 3 { return args[2], nil }; return nil, nil }
		}
	case "has":
		if len(args) >= 2 { if m, ok := args[0].(map[string]any); ok { _, ok2 := m[fmt.Sprint(args[1])]; return ok2, nil } }
	case "sort":
		if len(args) > 0 { arr := toAnySlice(args[0]); if arr != nil { cp := append([]any{}, arr...); sort.SliceStable(cp, func(i, j int) bool { return fmt.Sprint(cp[i]) < fmt.Sprint(cp[j]) }); return cp, nil } }
	case "reverse":
		if len(args) > 0 { arr := toAnySlice(args[0]); if arr != nil { cp := append([]any{}, arr...); for i, j := 0, len(cp)-1; i < j; i, j = i+1, j-1 { cp[i], cp[j] = cp[j], cp[i] }; return cp, nil }; if s, ok := args[0].(string); ok { r := []rune(s); for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 { r[i], r[j] = r[j], r[i] }; return string(r), nil } }
	case "uniq", "unique":
		if len(args) > 0 { arr := toAnySlice(args[0]); seen := map[string]bool{}; var out []any; for _, e := range arr { k := fmt.Sprintf("%#v", e); if !seen[k] { seen[k] = true; out = append(out, e) } }; if out == nil { out = []any{} }; return out, nil }
	case "first":
		if len(args) > 0 { arr := toAnySlice(args[0]); if len(arr) > 0 { return arr[0], nil } }
		return nil, nil
	case "last":
		if len(args) > 0 { arr := toAnySlice(args[0]); if len(arr) > 0 { return arr[len(arr)-1], nil } }
		return nil, nil
	case "toJSON":
		if len(args) > 0 { b, _ := json.Marshal(args[0]); return string(b), nil }
	case "fromJSON":
		if len(args) > 0 { var v any; _ = json.Unmarshal([]byte(fmt.Sprint(args[0])), &v); return v, nil }
	case "now":
		return time.Now(), nil
	}
	return nil, nil
}

func formatExprValue(v any) string {
	if v == nil {
		return "<nil>"
	}
	if _, ok := v.(*funcValue); ok {
		return "0x4dc280"
	}
	// Slices of entryValue etc are formatted by fmt using String methods.
	return fmt.Sprintf("%v", v)
}
