package main

import (
	"fmt"
	"strings"
	"time"
)

// callStatusFunc invokes the documented status-bar functions against the
// model's currently selected file.
func (m *model) callStatusFunc(name string, args []any) (any, error) {
	cur := m.currentEntry()
	var info interface {
	}
	_ = info
	switch name {
	case "Mode", "Size", "Owner", "ModTime":
		if cur == nil {
			return "", nil
		}
		fi, err := cur.Info()
		if err != nil {
			return "", err
		}
		switch name {
		case "Mode":
			return modeString(fi.Mode()), nil
		case "Size":
			return humanSize(fi.Size()), nil
		case "Owner":
			return ownerString(fi), nil
		case "ModTime":
			mt := fi.ModTime()
			if mt.Year() == time.Now().Year() {
				return mt.Format("Jan 2 15:04"), nil
			}
			return mt.Format("Jan 2 2006"), nil
		}
	case "PadLeft", "PadRight":
		// Both pad on the left in the original (PadRight shares the bug).
		if len(args) < 2 {
			return "", nil
		}
		s := fmt.Sprint(args[0])
		var n int64
		switch v := args[1].(type) {
		case int64:
			n = v
		case int:
			n = int64(v)
		case float64:
			n = int64(v)
		}
		if int64(len([]rune(s))) >= n {
			return s, nil
		}
		return strings.Repeat(" ", int(n)-len([]rune(s))) + s, nil
	case "Sprintf":
		if len(args) == 0 {
			return "", nil
		}
		format, _ := args[0].(string)
		return fmt.Sprintf(format, args[1:]...), nil
	}
	return "", nil
}

// statusText evaluates the compiled status bar for the current selection.
// It returns the text and whether it is an error rendering (unstyled).
func (m *model) statusText() (string, bool) {
	if m.statusProg == nil {
		return "", false
	}
	if m.currentEntry() == nil {
		return "", false
	}
	out, err := m.statusProg.run(m)
	if err != nil {
		return err.Error(), true
	}
	return formatExprValue(out), false
}
