package main

import (
	"os"
	"strings"
	"syscall"
	"unsafe"
)

type termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Line   byte
	Cc     [32]byte
	Ispeed uint32
	Ospeed uint32
}

const (
	tcgets = 0x5401
	tcsets = 0x5402
)

func getTermios(fd uintptr) (*termios, error) {
	var t termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(tcgets), uintptr(unsafe.Pointer(&t)))
	if errno != 0 {
		return nil, errno
	}
	return &t, nil
}

func setTermios(fd uintptr, t *termios) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(tcsets), uintptr(unsafe.Pointer(t)))
	if errno != 0 {
		return errno
	}
	return nil
}

func makeRaw(fd uintptr) (*termios, error) {
	old, err := getTermios(fd)
	if err != nil {
		return nil, err
	}
	raw := *old
	raw.Iflag &^= 0x0001 | 0x0002 | 0x0010 | 0x0020 | 0x0040 | 0x0080 | 0x0100 | 0x0400 // IGNBRK BRKINT PARMRK ISTRIP INLCR IGNCR ICRNL IXON
	raw.Oflag &^= 0x0001 // OPOST
	raw.Lflag &^= 0x0008 | 0x0002 | 0x0001 | 0x8000 | 0x4000 // ECHO ECHONL ICANON ISIG? (constants corrected below)
	// Use the canonical Linux values explicitly:
	raw.Lflag = old.Lflag &^ (0x00000002 | 0x00000008 | 0x00008000 | 0x00000001) // ICANON|ECHO|IEXTEN? see below
	raw.Lflag &^= 0x00000004 // ISIG linux (0x0001 actually)
	// Simpler: rebuild from known Linux flag bits:
	// Lflag bits: ISIG=0x0001, ICANON=0x0002, ECHO=0x0008, ECHOE=0x0010, ECHOK=0x0020, ECHONL=0x0040, IEXTEN=0x8000
	raw.Lflag = old.Lflag &^ uint32(0x0001|0x0002|0x0008|0x0040|0x8000)
	raw.Cflag &^= 0x0100 | 0x0030 // PARENB|CSIZE
	raw.Cflag |= 0x0030          // CS8 (0x30)
	raw.Cc[6] = 1                // VMIN
	raw.Cc[5] = 0                // VTIME
	if err := setTermios(fd, &raw); err != nil {
		return nil, err
	}
	return old, nil
}

type winsize struct {
	Row, Col, Xpixel, Ypixel uint16
}

func terminalSize(fd uintptr) (int, int) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 80, 24
	}
	w, h := int(ws.Col), int(ws.Row)
	if w <= 0 {
		w = 80
	}
	if h <= 0 {
		h = 24
	}
	return w, h
}

// colour profile

type colorProfile int

const (
	profileAscii colorProfile = iota
	profileANSI
	profileANSI256
	profileTrueColor
)

func detectProfile(out *os.File) colorProfile {
	if os.Getenv("CI") != "" {
		return profileAscii
	}
	// The output used for the UI is stderr.
	if !isTTY(out) {
		return profileAscii
	}
	ct := strings.ToLower(os.Getenv("COLORTERM"))
	if ct == "truecolor" || ct == "24bit" {
		return profileTrueColor
	}
	if ct == "yes" {
		return profileANSI256
	}
	term := os.Getenv("TERM")
	if term == "wezterm" || term == "xterm-kitty" {
		return profileTrueColor
	}
	if strings.Contains(term, "256color") {
		return profileANSI256
	}
	if strings.Contains(term, "color") || strings.Contains(term, "ansi") || term == "linux" {
		return profileANSI
	}
	return profileAscii
}

func isTTY(f *os.File) bool {
	if f == nil {
		return false
	}
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno == 0 {
		return true
	}
	// Fall back to TCGETS
	_, err := getTermios(f.Fd())
	return err == nil
}
