{"command":"cat > input.go <<'EOF'
package main

import (
	"strings"
	"unicode/utf8"
)

type keyEvent struct {
	key   string // bubbletea-like name: "up","down","j","ctrl+c","enter","backspace"," ","esc", etc.
	r     rune
	isRune bool
	other bool // an unrecognised special key
}

func runeKey(r rune) keyEvent {
	if r == ' ' {
		return keyEvent{key: " ", r: r, isRune: true}
	}
	return keyEvent{key: string(r), r: r, isRune: true}
}

// decodeInput converts a chunk of bytes read from the tty into key events.
func decodeInput(data []byte) []keyEvent {
	var out []keyEvent
	i := 0
	for i < len(data) {
		b := data[i]
		if b == 0x1b {
			// bracketed paste
			if i+5 < len(data) && string(data[i:i+6]) == "\x1b[200~" {
				end := strings.Index(string(data[i+6:]), "\x1b[201~")
				var paste string
				if end < 0 {
					paste = string(data[i+6:])
					i = len(data)
				} else {
					paste = string(data[i+6 : i+6+end])
					i = i + 6 + end + 6
				}
				for _, r := range paste {
					out = append(out, runeKey(r))
				}
				continue
			}
			if i+1 >= len(data) {
				out = append(out, keyEvent{key: "esc"})
				i++
				continue
			}
			// CSI
			if data[i+1] == '[' {
				j := i + 2
				// SGR mouse / private sequences: consume to final byte
				for j < len(data) && !(data[j] >= 0x40 && data[j] <= 0x7e) {
					j++
				}
				if j >= len(data) {
					out = append(out, keyEvent{key: "esc"})
					break
				}
				final := data[j]
				params := string(data[i+2 : j])
				out = append(out, csiKey(params, final))
				i = j + 1
				continue
			}
			if data[i+1] == 'O' && i+2 < len(data) {
				out = append(out, ss3Key(data[i+2]))
				i += 3
				continue
			}
			// Alt + rune
			r, size := utf8.DecodeRune(data[i+1:])
			if r != utf8.RuneError && size > 0 {
				out = append(out, keyEvent{key: "alt+" + string(r), other: true})
				i += 1 + size
				continue
			}
			out = append(out, keyEvent{key: "esc"})
			i++
			continue
		}
		switch b {
		case '\r':
			out = append(out, keyEvent{key: "enter"})
			i++
			continue
		case 0x7f:
			out = append(out, keyEvent{key: "backspace"})
			i++
			continue
		case '\t':
			out = append(out, keyEvent{key: "tab", other: true})
			i++
			continue
		case 0x03:
			out = append(out, keyEvent{key: "ctrl+c"})
			i++
			continue
		case 0x1a:
			out = append(out, keyEvent{key: "ctrl+z", other: true})
			i++
			continue
		}
		if b < 0x20 {
			// ctrl letters and others
			name := ""
			if b >= 1 && b <= 26 {
				name = "ctrl+" + string(rune('a'+b-1))
			} else {
				name = "ctrl+?"
			}
			out = append(out, keyEvent{key: name, other: true})
			i++
			continue
		}
		r, size := utf8.DecodeRune(data[i:])
		if r == utf8.RuneError {
			i++
			continue
		}
		out = append(out, runeKey(r))
		i += size
	}
	return out
}

func ss3Key(c byte) keyEvent {
	switch c {
	case 'A':
		return keyEvent{key: "up"}
	case 'B':
		return keyEvent{key: "down"}
	case 'C':
		return keyEvent{key: "right"}
	case 'D':
		return keyEvent{key: "left"}
	case 'H':
		return keyEvent{key: "home"}
	case 'F':
		return keyEvent{key: "end"}
	case 'P', 'Q', 'R', 'S':
		return keyEvent{key: "f", other: true}
	}
	return keyEvent{key: "unknown", other: true}
}

func csiKey(params string, final byte) keyEvent {
	// mouse SGR: params starts with '<'
	if strings.HasPrefix(params, "<") {
		return keyEvent{key: "mouse", other: true}
	}
	// Shift-tab
	if final == 'Z' {
		return keyEvent{key: "shift+tab", other: true}
	}
	parts := strings.Split(params, ";")
	code := parts[0]
	mod := ""
	if len(parts) > 1 {
		mod = parts[1]
	}
	shift := mod == "2"
	_ = shift
	switch final {
	case 'A':
		if shift { return keyEvent{key: "shift+up"} }
		return keyEvent{key: "up"}
	case 'B':
		if shift { return keyEvent{key: "shift+down"} }
		return keyEvent{key: "down"}
	case 'C':
		if shift { return keyEvent{key: "shift+right"} }
		return keyEvent{key: "right"}
