package main

import (
	"os"
	"strconv"
	"strings"
)

type rgb struct{ r, g, b int }

type colorVal struct {
	isRGB   bool
	ansi    int
	hasANSI bool
	none    bool
	c       rgb
}

func parseColor(s string) colorVal {
	if strings.HasPrefix(s, "#") {
		h := s[1:]
		if len(h) == 3 {
			h = string([]byte{h[0], h[0], h[1], h[1], h[2], h[2]})
		}
		if len(h) == 6 {
			v, err := strconv.ParseUint(h, 16, 32)
			if err == nil {
				return colorVal{isRGB: true, c: rgb{int(v >> 16 & 0xff), int(v >> 8 & 0xff), int(v & 0xff)}}
			}
		}
		return colorVal{none: true}
	}
	if v, err := strconv.ParseInt(s, 10, 32); err == nil && v >= 0 && v <= 255 {
		return colorVal{ansi: int(v), hasANSI: true}
	}
	return colorVal{none: true}
}

var palette16 = []rgb{
	{0, 0, 0}, {170, 0, 0}, {0, 170, 0}, {170, 85, 0}, {0, 0, 170}, {170, 0, 170}, {0, 170, 170}, {170, 170, 170},
	{85, 85, 85}, {255, 85, 85}, {85, 255, 85}, {255, 255, 85}, {85, 85, 255}, {255, 85, 255}, {85, 255, 255}, {255, 255, 255},
}

func paletteRGB(idx int) rgb {
	if idx < 0 {
		idx = 0
	}
	if idx > 255 {
		idx = 255
	}
	if idx < 16 {
		return palette16[idx]
	}
	if idx < 232 {
		v := idx - 16
		levels := []int{0, 95, 135, 175, 215, 255}
		return rgb{levels[v/36], levels[(v%36)/6], levels[v%6]}
	}
	g := 8 + (idx-232)*10
	return rgb{g, g, g}
}

func dist(a, b rgb) int {
	dr := a.r - b.r
	dg := a.g - b.g
	db := a.b - b.b
	return dr*dr + dg*dg + db*db
}

func nearestANSI256(c rgb) int {
	best, bestD := 0, 1<<62
	for i := 0; i < 256; i++ {
		if d := dist(c, paletteRGB(i)); d < bestD {
			best, bestD = i, d
		}
	}
	return best
}
func nearestANSI16(c rgb) int {
	best, bestD := 0, 1<<62
	for i := 0; i < 16; i++ {
		if d := dist(c, palette16[i]); d < bestD {
			best, bestD = i, d
		}
	}
	return best
}

// seq returns the SGR parameter for a colour in the given position
// (foreground if fg is true).
func (col colorVal) seq(profile colorProfile, fg bool) string {
	if col.none || profile == profileAscii {
		return ""
	}
	var c rgb
	if col.isRGB {
		c = col.c
	} else if col.hasANSI {
		switch profile {
		case profileTrueColor:
			c = paletteRGB(col.ansi)
			if fg {
				return "38;2;" + strconv.Itoa(c.r) + ";" + strconv.Itoa(c.g) + ";" + strconv.Itoa(c.b)
			}
			return "48;2;" + strconv.Itoa(c.r) + ";" + strconv.Itoa(c.g) + ";" + strconv.Itoa(c.b)
		case profileANSI256:
			if fg {
				return "38;5;" + strconv.Itoa(col.ansi)
			}
			return "48;5;" + strconv.Itoa(col.ansi)
		case profileANSI:
			idx := nearestANSI16(paletteRGB(col.ansi))
			if fg {
				if idx < 8 {
					return strconv.Itoa(30 + idx)
				}
				return strconv.Itoa(90 + idx - 8)
			}
			if idx < 8 {
				return strconv.Itoa(40 + idx)
			}
			return strconv.Itoa(100 + idx - 8)
		}
		return ""
	} else {
		return ""
	}
	// RGB source
	switch profile {
	case profileTrueColor:
		if fg {
			return "38;2;" + strconv.Itoa(c.r) + ";" + strconv.Itoa(c.g) + ";" + strconv.Itoa(c.b)
		}
		return "48;2;" + strconv.Itoa(c.r) + ";" + strconv.Itoa(c.g) + ";" + strconv.Itoa(c.b)
	case profileANSI256:
		idx := nearestANSI256(c)
		if fg {
			return "38;5;" + strconv.Itoa(idx)
		}
		return "48;5;" + strconv.Itoa(idx)
	case profileANSI:
		idx := nearestANSI16(c)
		if fg {
			if idx < 8 {
				return strconv.Itoa(30 + idx)
			}
			return strconv.Itoa(90 + idx - 8)
		}
		if idx < 8 {
			return strconv.Itoa(40 + idx)
		}
		return strconv.Itoa(100 + idx - 8)
	}
	return ""
}

type style struct {
	fg, bg colorVal
	hasFg  bool
	hasBg  bool
}

func (s style) render(profile colorProfile, text string) string {
	if profile == profileAscii {
		return text
	}
	var prefix strings.Builder
	if s.hasFg {
		if seq := s.fg.seq(profile, true); seq != "" {
			prefix.WriteString("\x1b[" + seq + "m")
		}
	}
	if s.hasBg {
		if seq := s.bg.seq(profile, false); seq != "" {
			prefix.WriteString("\x1b[" + seq + "m")
		}
	}
	if prefix.Len() == 0 {
		return text
	}
	var suffix strings.Builder
	if s.hasFg && s.fg.seq(profile, true) != "" {
		suffix.WriteString("\x1b[39m")
	}
	if s.hasBg && s.bg.seq(profile, false) != "" {
		suffix.WriteString("\x1b[49m")
	}
	return prefix.String() + text + suffix.String()
}

func hexColor(s string) colorVal { return parseColor(s) }

var _ = os.Getenv
