func parseOpenWith(s string) map[string]string {
	out := map[string]string{}
	if s == "" {
		return out
	}
	for _, part := range strings.Split(s, ";") {
		if part == "" {
			continue
		}
		idx := strings.Index(part, ":")
		if idx < 0 {
			continue
		}
		ext := part[:idx]
		cmd := part[idx+1:]
		out[ext] = cmd
	}
	return out
