// ---------------- program loop ----------------

type renderer struct {
	out           *os.File
	profile       colorProfile
	alt           bool
	started       bool
	prevLines     int
	normalPrev    int
	width, height int
}

func runProgram(m *model, tty *os.File) (final *model, panicked bool) {
	oldState, err := makeRaw(tty.Fd())
	if err != nil {
		// If the tty cannot be made raw, continue anyway.
		oldState = nil
	}
	out := os.Stderr
	r := &renderer{out: out, profile: m.profile}
	// initial size
	w, h := terminalSize(tty.Fd())
	m.width, m.height = w, h
	r.width, r.height = w, h

	restore := func() {
		if r.alt {
			fmt.Fprint(out, "\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l\x1b[?1049l\x1b[?25h")
			r.alt = false
		} else {
			if r.started {
				fmt.Fprint(out, "\r\n")
			}
			fmt.Fprint(out, "\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")
		}
		if oldState != nil {
			_ = setTermios(tty.Fd(), oldState)
		}
	}

	defer func() {
		if rec := recover(); rec != nil {
			// Bubbletea-style recovery for panics raised while handling a
			// message (for example fileInfo on a dangling symlink).
			restore()
			fmt.Fprintf(os.Stdout, "Caught panic:\n\n%v\n\nRestoring terminal...\n\n", rec)
			debug.PrintStack()
			final = nil
			panicked = true
		}
	}()

	// startup sequences
	if m.preview {
		fmt.Fprint(out, "\x1b[?25l\x1b[?1049h\x1b[2J\x1b[H\x1b[?25l\x1b[?2004h")
		r.alt = true
	} else {
		fmt.Fprint(out, "\x1b[?25l\x1b[?2004h")
	}
	r.started = true
	r.render(m, m.View())

	// Configure a short read timeout so timers and resizes are polled.
	if oldState != nil {
		if st, err2 := getTermios(tty.Fd()); err2 == nil {
			st.Cc[6] = 0 // VMIN
			st.Cc[5] = 1 // VTIME 0.1s
			_ = setTermios(tty.Fd(), st)
		}
	}

	buf := make([]byte, 4096)
	for !m.quit {
		// timers for pending deletions
		now := time.Now()
		changed := false
		for i := 0; i < len(m.pending); {
			p := m.pending[i]
			if !now.Before(p.next) {
				p.count--
				if p.count < 0 {
					// execute this deletion
					executeRemove(m.removeCmd, m.removeCmdSet, p.path)
					m.pending = append(m.pending[:i], m.pending[i+1:]...)
					changed = true
					continue
				}
				p.next = p.next.Add(time.Second)
				changed = true
			}
			i++
		}
		if changed {
			syncAlt(m, r)
			r.render(m, m.View())
		}
		// resize?
		if nw, nh := terminalSize(tty.Fd()); nw != m.width || nh != m.height {
			m.width, m.height = nw, nh
			r.width, r.height = nw, nh
			syncAlt(m, r)
			r.render(m, m.View())
		}
		n, readErr := tty.Read(buf)
		if n <= 0 {
			if readErr != nil {
				// EOF / error on the tty: treat as quit without cd?
				break
			}
			continue
		}
		events := decodeInput(buf[:n])
		for _, ev := range events {
			editor := m.handleKey(ev)
			if editor != nil {
				runEditor(m, tty, r, oldState, editor)
				syncAlt(m, r)
				r.render(m, m.View())
			} else {
				syncAlt(m, r)
				r.render(m, m.View())
			}
			if m.quit {
				break
			}
		}
	}
	restore()
	return m, false
}

func syncAlt(m *model, r *renderer) {
	if m.preview && !r.alt {
		fmt.Fprint(r.out, "\x1b[?1049h\x1b[2J\x1b[H\x1b[?25l")
		r.alt = true
		r.prevLines = 0
	} else if !m.preview && r.alt {
		fmt.Fprint(r.out, "\x1b[?1049l\x1b[?25l")
		r.alt = false
		r.prevLines = r.normalPrev
	}
}

func (r *renderer) render(m *model, view string) {
	r.width, r.height = m.width, m.height
	lines := strings.Split(view, "\n")
	if r.alt {
		if r.height > 0 && len(lines) > r.height {
			lines = lines[:r.height]
		}
		var sb strings.Builder
		sb.WriteString("\x1b[H")
		for i, line := range lines {
			sb.WriteString("\x1b[2K\r")
			sb.WriteString(line)
			if i != len(lines)-1 {
				sb.WriteString("\r\n")
			}
		}
		sb.WriteString("\x1b[J")
		fmt.Fprint(r.out, sb.String())
		r.prevLines = len(lines)
		return
	}
	// normal renderer
	var sb strings.Builder
	if r.prevLines > 0 {
		if r.prevLines > 1 {
			sb.WriteString(fmt.Sprintf("\x1b[%dA", r.prevLines-1))
		}
		sb.WriteString("\r")
	}
	for i, line := range lines {
		sb.WriteString("\x1b[2K\r")
		sb.WriteString(line)
		if i != len(lines)-1 {
			sb.WriteString("\r\n")
		}
	}
	if r.prevLines > len(lines) {
		diff := r.prevLines - len(lines)
		for i := 0; i < diff; i++ {
			sb.WriteString("\r\n\x1b[2K\r")
		}
		if diff > 0 {
			sb.WriteString(fmt.Sprintf("\x1b[%dA", diff))
		}
	}
	fmt.Fprint(r.out, sb.String())
	r.prevLines = len(lines)
	r.normalPrev = len(lines)
}

func runEditor(m *model, tty *os.File, r *renderer, oldState *termios, cmd *exec.Cmd) {
	// Release the terminal.
	if r.alt {
		fmt.Fprint(r.out, "\x1b[2K\r\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l\x1b[?1049l\x1b[?25h")
	} else {
		fmt.Fprint(r.out, "\x1b[2K\r\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")
	}
	if oldState != nil {
		_ = setTermios(tty.Fd(), oldState)
	}
	cmd.Stdin = tty
	cmd.Stdout = os.Stderr
	cmd.Stderr = os.Stderr
	_ = cmd.Run()
	// Re-acquire the terminal.
	if _, err := makeRaw(tty.Fd()); err == nil {
		if st, err2 := getTermios(tty.Fd()); err2 == nil {
			st.Cc[6] = 0
			st.Cc[5] = 1
			_ = setTermios(tty.Fd(), st)
		}
	}
	if m.preview {
		fmt.Fprint(r.out, "\x1b[?25l\x1b[?1049h\x1b[2J\x1b[H\x1b[?25l\x1b[?2004h")
		r.alt = true
		r.prevLines = 0
	} else {
		fmt.Fprint(r.out, "\x1b[?25l\x1b[?2004h")
		// the next render will move up over the old frame as bubbletea does;
		// r.prevLines is intentionally retained.
	}
}

// editorCommand builds the command to open the given absolute path.
func (m *model) editorCommand(absPath, fileName string) *exec.Cmd {
	ext := strings.ToLower(strings.TrimPrefix(filepath.Ext(fileName), "."))
	cmdStr, ok := m.openWith[ext]
	if !ok {
		cmdStr = os.Getenv("WALK_EDITOR")
		if cmdStr == "" {
			cmdStr = os.Getenv("EDITOR")
		}
		if cmdStr == "" {
			cmdStr = "less"
		}
	}
	fields := strings.Fields(cmdStr)
	if len(fields) == 0 {
		fields = []string{"less"}
	}
	args := append(append([]string{}, fields[1:]...), absPath)
	return exec.Command(fields[0], args...)
}
