	if m.showHelp && !preserving[key] && !ev.isRune {
		// special keys: movement etc dismiss, others are handled below
		m.showHelp = false
	} else if m.showHelp && ev.isRune && !preserving[key] {
		// runes other than preserved ones dismiss help, except '?' handled below
		if key != "?" {
