			// in the generic flow; mark that help should be dismissed for them
			// Movement and action runes dismiss (handled there); generic letters too.
			m.showHelp = false
		}
	}
	// In fuzzy/search mode, rune keys type into the query (except space).
	if m.fuzzy && ev.isRune && key != " " {
		if ev.r == '/' {
			if m.searching {
				// toggle search off
				m.searching = false
				m.fuzzy = false
				m.query = ""
				return nil
			}
			// persistent fuzzy: '/' is typed
			m.query += "/"
			m.fuzzySearch()
			return nil
		}
		m.query += string(ev.r)
		m.fuzzySearch()
		return nil
	}
	if m.fuzzy {
		switch key {
		case "backspace":
			if m.query != "" {
				r := []rune(m.query)
				m.query = string(r[:len(r)-1])
				return nil
			}
			if m.searching {
				m.searching = false
				m.fuzzy = false
				return nil
			}
			// persistent fuzzy with empty query: fall through to parent navigation
			return m.navBack()
		case "down", "up", "left", "right", "shift+down", "shift+up", "shift+left", "shift+right", "pgup", "pgdown", "home", "end":
