func (m *model) clearMessageAndMark() {
	m.copied = ""
	m.marked = false
}

func (m *model) doQuit() {
	// Flush pending deletions immediately.
	for _, p := range m.pending {
		executeRemove(m.removeCmd, m.removeCmdSet, p.path)
	}
	m.pending = nil
	m.quit = true
}

func (m *model) move(key string) {
	n := len(m.files)
	if n == 0 {
		return
	}
	cols, rows := m.rowsCols()
	if rows <= 0 {
		rows = n
	}
	if cols <= 0 {
		cols = 1
	}
	c := m.cursor
	switch key {
	case "down":
		c = (c + 1) % n
		if c < 0 { c += n }
	case "up":
		c = (c - 1) % n
		if c < 0 { c += n }
	case "right":
		col := 0
		row := c
		if rows > 0 {
			col = c / rows
			row = c % rows
		}
		col = (col + 1) % cols
		c = col*rows + row
		if c >= n {
			c = n - 1
		}
	case "left":
		col := 0
		row := c
		if rows > 0 {
			col = c / rows
			row = c % rows
		}
		col = (col - 1 + cols) % cols
		c = col*rows + row
		if c >= n {
			c = n - 1
		}
	case "shift+down":
		if rows > 0 {
			start := (c / rows) * rows
			c = start + rows - 1
			if c >= n { c = n - 1 }
		}
	case "shift+up":
		if rows > 0 {
			c = (c / rows) * rows
		}
	case "shift+right":
		if rows > 0 {
			col := c / rows
			c = c + (cols-1-col)*rows
			if c >= n { c = n - 1 }
		}
	case "shift+left":
		if rows > 0 {
			col := c / rows
			c = c - col*rows
		}
	case "home":
		c = 0
	case "end":
		c = n - 1
	}
	m.cursor = c
}

func (m *model) fuzzySearch() {
	if len(m.files) == 0 || m.query == "" {
		return
	}
	idx := bestFuzzyMatch(m.query, m.files)
	if idx >= 0 {
		m.cursor = idx
	}
}

func (m *model) navBack() *exec.Cmd {
	if m.path == filepath.Dir(m.path) {
		return nil
	}
	// In fuzzy persistent mode the query is already empty here.
	old := filepath.Base(m.path)
	m.path = filepath.Dir(m.path)
	m.marked = false
	m.load()
	if m.err == nil {
		for i, f := range m.files {
			if f.Name() == old {
				m.cursor = i
				break
			}
		}
	}
	return nil
}

func (m *model) doEnter() *exec.Cmd {
	cur := m.currentEntry()
	if cur == nil {
		return nil
	}
	info := fileInfo(m.path, cur.DirEntry)
	if info.IsDir() {
		m.copied = ""
		m.marked = false
		// clear a temporary search
		if m.searching {
			m.searching = false
			m.fuzzy = false
		}
		m.query = ""
		m.path = filepath.Join(m.path, cur.Name())
		m.cursor = 0
		m.load()
		return nil
	}
	abs := filepath.Join(m.path, cur.Name())
	return m.editorCommand(abs, cur.Name())
}

func (m *model) doDelete() {
	cur := m.currentEntry()
	if cur == nil {
		return
	}
	if !m.marked {
		m.marked = true
		return
	}
	// confirm deletion
