	// global abort / quit that are not runes
	if key == "ctrl+c" {
		m.aborted = true
		m.quit = true
		return nil
	}
	if key == "esc" {
		m.doQuit()
		return nil
	}

	// When in help, the preserving keys act without dismissing help.
	preserving := map[string]bool{
		" ": true, "backspace": true, "d": true, "delete": true, "y": true, "?": true,
	}
	if m.showHelp && !preserving[key] && !ev.isRune {
		// special keys: movement etc dismiss, others are handled below
		m.showHelp = false
	} else if m.showHelp && ev.isRune && !preserving[key] {
		// runes other than preserved ones dismiss help, except '?' handled below
		if key != "?" {
			// '/', '.', movement letters, enter substitutes etc are handled
			// in the generic flow; mark that help should be dismissed for them
			// Movement and action runes dismiss (handled there); generic letters too.
			m.showHelp = false
		}
	}
	// In fuzzy/search mode, rune keys type into the query (except space).
	if m.fuzzy && ev.isRune && key != " " {
		if ev.r == '/' {
			if m.searching {
				// toggle search off
				m.searching = false
				m.fuzzy = false
				m.query = ""
				return nil
			}
			// persistent fuzzy: '/' is typed
			m.query += "/"
			m.fuzzySearch()
			return nil
		}
		m.query += string(ev.r)
		m.fuzzySearch()
		return nil
	}
	if m.fuzzy {
		switch key {
		case "backspace":
			if m.query != "" {
				r := []rune(m.query)
				m.query = string(r[:len(r)-1])
				return nil
			}
			if m.searching {
				m.searching = false
				m.fuzzy = false
				return nil
			}
			// persistent fuzzy with empty query: fall through to parent navigation
			return m.navBack()
		case "down", "up", "left", "right", "shift+down", "shift+up", "shift+left", "shift+right", "pgup", "pgdown", "home", "end":
			m.clearMessageAndMark()
			m.move(key)
			return nil
		case "enter":
			// leave search mode, then perform the enter action
			wasSearching := m.searching
			m.query = ""
			m.searching = false
			if wasSearching {
				m.fuzzy = false
			}
