	case "?":
		m.showHelp = !m.showHelp
		return nil
	case " ":
		m.preview = !m.preview
		return nil
	case "backspace":
		return m.navBack()
	case "d", "delete":
		m.doDelete()
		return nil
	case "y":
		m.doCopy()
		return nil
	}

