package main

import (
	"strings"
	"unicode"
)

// bestFuzzyMatch returns the index of the best fuzzy match for query among
// files, or -1.  Matching is a case-insensitive subsequence match with
// bonuses for word starts, separators and consecutive characters, and a
// penalty for unmatched characters.  Ties go to the later file.
func bestFuzzyMatch(query string, files []entry) int {
	best := -1
	bestScore := -1 << 30
	for i, f := range files {
		score, ok := fuzzyScore(query, f.Name())
		if !ok {
			continue
		}
		if score >= bestScore {
			bestScore = score
			best = i
		}
	}
	return best
}

func fuzzyScore(pattern, target string) (int, bool) {
	if pattern == "" {
		return 0, true
	}
	p := []rune(strings.ToLower(pattern))
	tLow := []rune(strings.ToLower(target))
	tOrig := []rune(target)
	// DP over positions in the target for the optimal subsequence alignment.
	// dp[i] is the best score for matching the pattern prefix ending at a
	// match that uses target position i (not used for large inputs in practice).
	neg := -1 << 29
	// prev scores for pattern prefix length-1
	m, n := len(p), len(tLow)
	if m > n && !strings.ContainsRune(pattern, '/') {
		// still possible only if subsequence exists; length check is a shortcut
		// but a pattern longer than the target can never be a subsequence.
		return 0, false
	}
	prev := make([]int, n)
	cur := make([]int, n)
	for i := range prev {
		prev[i] = neg
	}
	for pi := 0; pi < m; pi++ {
		for i := range cur {
			cur[i] = neg
		}
		bestSoFar := neg
		for ti := 0; ti < n; ti++ {
			if ti > 0 && prev[ti-1] > bestSoFar {
				// not used directly
			}
			_ = bestSoFar
			if tLow[ti] == p[pi] {
				bonus := 0
				if ti == 0 {
					bonus += 15
				} else {
					prevCh := tOrig[ti-1]
					if prevCh == '/' || prevCh == '_' || prevCh == '-' || prevCh == '.' || prevCh == ' ' || prevCh == '\\' {
						bonus += 12
					}
					if unicode.IsLower(prevCh) && unicode.IsUpper(tOrig[ti]) {
						bonus += 10
					}
				}
				var val int
				if pi == 0 {
					// penalty for leading unmatched characters
					val = 10 + bonus - ti
				} else {
					// best previous score up to ti-1
					bestPrev := neg
					for k := 0; k < ti; k++ {
						s := prev[k]
						if k == ti-1 {
							s += 8 // consecutive bonus
						}
						if s > bestPrev {
							bestPrev = s
						}
					}
					if bestPrev == neg {
						continue
					}
					val = bestPrev + 10 + bonus
				}
				cur[ti] = val
			}
		}
		copy(prev, cur)
	}
	best := neg
	for _, v := range prev {
		if v > best {
			best = v
		}
	}
	if best == neg {
		return 0, false
	}
	// penalty for unmatched target characters
	unmatched := n - m
	if unmatched < 0 {
		unmatched = 0
	}
	return best - unmatched, true
}
EOF
