package main

import "strings"

// truncateLineANSI truncates a line to a visible width, preserving ANSI
// escape sequences that appear before the cut.
func truncateLineANSI(s string, max int) string {
	if max <= 0 {
		return s
	}
	if visualWidth(s) <= max {
		return s
	}
	var b strings.Builder
	width := 0
	i := 0
	hasEsc := false
	for i < len(s) {
		if s[i] == 0x1b {
			// copy escape sequence
			j := i + 1
			if j < len(s) && s[j] == '[' {
				j++
				for j < len(s) && !(s[j] >= 0x40 && s[j] <= 0x7e) {
					j++
				}
				if j < len(s) {
					j++
				}
			} else if j < len(s) && s[j] == ']' {
				// OSC ... terminated by BEL or ST
				j++
				for j < len(s) && s[j] != 0x07 && !(s[j] == '\\' && j > i && s[j-1] == 0x1b) {
					j++
				}
				if j < len(s) {
					j++
				}
			} else {
				j = i + 2
				if j > len(s) {
					j = len(s)
				}
			}
			b.WriteString(s[i:j])
			hasEsc = true
			i = j
			continue
		}
		r := rune(s[i])
		// decode utf8 rune manually via strings
		rn, size := decodeRuneInString(s[i:])
		r = rn
		rw := 1
		if r == '\t' {
			rw = 8 - (width % 8)
		} else {
			rw = runeWidth(r)
		}
		if width+rw > max {
			break
		}
		b.WriteString(s[i : i+size])
		width += rw
		i += size
	}
	if hasEsc {
		b.WriteString("\x1b[0m\x1b[39m\x1b[49m")
	}
	return b.String()
}

func decodeRuneInString(s string) (rune, int) {
	// Avoid importing unicode/utf8 twice here; use a tiny wrapper through
	// the standard behaviour by converting the first bytes.
	// This function is replaced by utf8.DecodeRuneInString in practice via
	// build-tag-free indirection below.
	return utf8Decode(s)
}
EOF
